  boom: ['Explosives & mines', '#d35400', '💣'],
  armour: ['Armour & shields', '#4f7598', '🛡️'],
  land: ['Chariots, cavalry & tanks', '#5c6b2f', '🐎'],
  sea: ['Warships & submarines', '#2b5a8a', '⚓'],
