window.WEAPON_ERAS = [
  { n: 'Stone Age', to: -3300, range: '3.3 million years ago – 3300 BCE', intro: 'For almost all of human history, weapons were the same as tools: shaped stone, sharpened wood and bone, used for hunting first and for fighting later.' },
  { n: 'Bronze Age', to: -1200, range: '3300 – 1200 BCE', intro: 'Copper mixed with tin made bronze, hard enough for the first swords and armour. Kingdoms grew, and with them came chariots and professional soldiers.' },
  { n: 'Iron Age & the classical world', to: 500, range: '1200 BCE – 500 CE', intro: 'Iron was common and cheap, so whole armies could be armed. Greek, Roman, Persian, Indian and Chinese states built drilled infantry, siege machines and navies.' },
  { n: 'Middle Ages', to: 1450, range: '500 – 1450', intro: 'Armoured knights, castles and the bows and siege engines that beat them. In China, gunpowder was invented and slowly spread west.' },
  { n: 'Age of gunpowder', to: 1800, range: '1450 – 1800', intro: 'Guns and cannon changed armies, ships and fortresses. Muskets with bayonets replaced pikes, and sailing warships carried empires across the oceans.' },
  { n: 'Industrial age', to: 1914, range: '1800 – 1914', intro: 'Factories made weapons in huge numbers. Rifling, breech-loading, smokeless powder and machine guns made battlefields far deadlier.' },
  { n: 'World Wars', to: 1946, range: '1914 – 1945', intro: 'Two world wars brought tanks, aircraft, submarines, poison gas, radar, rockets and finally the atomic bomb.' },
  { n: 'Cold War', to: 1991, range: '1946 – 1991', intro: 'The USA and the Soviet Union raced to build nuclear missiles, jets, nuclear submarines and guided weapons, while treaties tried to limit them.' },
  { n: 'Modern era', to: 99999, range: '1991 – today', intro: 'Precision guidance, drones, cyber attacks, missile defence and lasers. Treaties ban some weapons, such as land mines and chemical weapons.' }
];
window.WEAPONS = [
  // ---------------- Stone Age
  { id: 'oldowan-chopper', n: 'Stone chopper (Oldowan tools)', c: 'impact', y: -2600000, d: 'c. 2.6 million years ago', r: 'East Africa (Ethiopia, Kenya)', w: 'Early humans (Homo habilis and relatives)', s: 'The oldest common stone tools: river pebbles with a few flakes knocked off to give a sharp edge, used to cut meat and crack bones.', how: 'Striking one stone against another breaks off flakes, leaving a sharp edge. The flakes themselves were also used as small knives.', use: 'Mainly for butchering animals. They were tools long before they were weapons, but every later weapon grew out of this skill.', ev: 'Even older stone tools, about 3.3 million years old, were found at Lomekwi in Kenya in 2015.', f: 'Oldowan tools are named after Olduvai Gorge in Tanzania, where Louis and Mary Leakey found many of them.', p: ['chopper'], x: ['hand-axe', ['invention-atlas.html#stone-tools', 'Stone tools in the Invention Atlas']] },
  { id: 'hand-axe', n: 'Hand axe', alt: 'Acheulean hand axe', c: 'impact', y: -1760000, d: 'c. 1.76 million years ago', r: 'Africa, then Europe and Asia', w: 'Homo erectus', s: 'A teardrop-shaped stone worked on both sides — the “Swiss army knife” of the Stone Age, made the same way for over a million years.', how: 'The maker planned the shape and removed flakes from both faces with a hammerstone, then with softer bone or antler hammers for a fine edge.', use: 'Cutting meat, digging, woodworking and probably defence. It needed planning and teaching, so it tells us about early minds.', ev: 'The style is called Acheulean after Saint-Acheul in France, but the oldest examples come from Kokiselei in Kenya.', f: 'Hand axes were made for about 1.5 million years, far longer than any other human design.', p: ['handaxe'], x: ['oldowan-chopper', 'stone-spear'] },
  { id: 'stone-spear', n: 'Stone-tipped spear', c: 'pole', y: -500000, d: 'c. 500,000 years ago', r: 'Southern Africa (Kathu Pan)', w: 'Homo heidelbergensis', s: 'A wooden shaft with a sharp stone point tied or glued to its tip — the first weapon made from more than one part.', how: 'A stone point was “hafted” to the shaft with sinew and natural glues such as birch tar or plant resin.', use: 'Hunting large animals from close range. Later, Neanderthals and modern humans used hafted spears widely.', ev: 'Points about 500,000 years old from Kathu Pan, South Africa, show impact damage from being thrust into animals.', f: 'Making glue from birch bark needs controlled heat — Neanderthals could already do it.', p: ['spear', { head: 'stone' }], x: ['wooden-spear', 'atlatl'] },
  { id: 'wooden-spear', n: 'Wooden throwing spear', alt: 'Schöningen spears', c: 'pole', y: -300000, d: 'c. 300,000 years ago', r: 'Germany (Schöningen)', w: 'Early humans (Homo heidelbergensis or early Neanderthals)', s: 'Long spears carved from spruce and pine, shaped like modern javelins, found beside the bones of butchered wild horses.', how: 'The heaviest part was near the front, like a modern javelin, so they flew straight when thrown.', use: 'Group hunting of horses and other large animals.', ev: 'The Schöningen spears, found in a coal mine in the 1990s, are the oldest complete hunting weapons ever found.', f: 'Wood rarely survives — these did because they were sealed in wet, airless mud.', p: ['spear', { head: 'wood', long: 1 }], x: ['stone-spear', 'pilum'] },
  { id: 'bow-arrow', n: 'Bow and arrow', c: 'ranged', y: -64000, d: 'c. 64,000 years ago', r: 'Southern Africa (Sibudu Cave)', w: 'Early modern humans', s: 'A bent stick and a string store energy and release it into a light arrow, letting a hunter strike from a safe distance.', how: 'Drawing the string bends the bow, storing energy like a spring. Releasing it pushes the arrow forward much faster than a hand could throw.', use: 'Hunting everywhere humans lived, and later war. Bows stayed important in battle until guns took over in the 1600s.', ev: 'Tiny stone arrowheads with traces of glue and blood from Sibudu Cave, South Africa, are about 64,000 years old.', f: 'Ötzi the Iceman, who died about 3300 BCE, carried an unfinished yew bow and 14 arrows.', p: ['bow'], x: ['composite-bow', 'longbow', 'crossbow-china'] },
  { id: 'atlatl', n: 'Spear-thrower', alt: 'Atlatl, woomera', c: 'ranged', y: -20000, d: 'by c. 20,000 years ago', r: 'Europe, Americas, Australia', w: 'Upper Palaeolithic hunters', s: 'A short stick with a hook that holds the end of a dart, making the thrower’s arm longer so the dart flies much faster.', how: 'The thrower works like an extra arm joint: the longer lever moves the dart’s end faster at the moment of release.', use: 'Hunting reindeer, mammoth and bison. The Aztecs still used atlatls against Spanish armour in 1521.', ev: 'Carved spear-throwers decorated with animals, about 17,000 years old, were found in French caves.', f: '“Atlatl” is the Aztec (Nahuatl) word; in Australia the same idea is called a woomera.', p: ['atlatl'], x: ['bow-arrow', 'stone-spear'] },
  { id: 'boomerang', n: 'Throwing stick and boomerang', c: 'ranged', y: -21000, d: 'c. 23,000 years ago', r: 'Poland (oldest find) and Australia', w: 'Stone Age hunters', s: 'A curved, flat stick thrown spinning at birds and small animals. Only light returning boomerangs come back; heavy hunting ones fly straight.', how: 'The stick is shaped like a wing. Spinning gives it stability; a returning boomerang’s two wings make it turn in a circle.', use: 'Hunting, fighting and sport, especially among Aboriginal Australians, who have used them for at least 10,000 years.', ev: 'A boomerang carved from mammoth tusk, about 23,000 years old, was found in Obłazowa Cave in Poland.', f: 'Tutankhamun’s tomb contained a collection of throwing sticks and boomerangs.', p: ['boomerang'], x: ['sling'] },
  { id: 'sling', n: 'Sling', c: 'ranged', y: -7000, d: 'by c. 7000 BCE', r: 'Near East', w: 'Neolithic farmers and herders', s: 'Two cords and a pouch. Whirled and released, it hurls a stone or a clay or lead bullet fast enough to break bones.', how: 'Swinging the sling makes the pouch travel fast in a circle; letting go of one cord frees the stone along a straight line.', use: 'Cheap and deadly. Slingers from the Balearic Islands and Rhodes served in Greek, Carthaginian and Roman armies.', ev: 'The Bible’s story of David and Goliath is the most famous sling shot in history.', f: 'Ancient lead sling bullets were sometimes cast with insults or jokes, such as “take that!”.', p: ['sling'], x: ['bow-arrow'] },
  { id: 'stone-mace', n: 'Stone mace', c: 'impact', y: -6000, d: 'c. 6000 BCE', r: 'Near East and Egypt', w: 'Neolithic peoples', s: 'A heavy stone head on a wooden handle, made for striking people rather than hunting — one of the first true weapons of war.', how: 'Putting the weight at the end of a handle makes the head move fast and hit hard.', use: 'Close combat. In Egypt the mace became a symbol of royal power.', ev: 'The Narmer Palette (c. 3100 BCE) shows King Narmer raising a mace over an enemy as Egypt is united.', f: 'Ceremonial maces are still carried in some parliaments today, such as the UK House of Commons.', p: ['mace', { type: 'stone' }], x: ['flanged-mace', 'wooden-club'] },
  { id: 'wooden-club', n: 'Wooden club', c: 'impact', y: -10000, d: 'Prehistoric (date unknown)', r: 'Worldwide', w: 'Hunters and warriors everywhere', s: 'A heavy stick, often with a knob at the end. Simple, universal and used in every part of the world.', how: 'A thicker, heavier end puts more weight into each blow.', use: 'Hunting and fighting. Many cultures made beautiful carved clubs, like the Māori patu and Fijian war clubs.', ev: 'Wooden clubs survive rarely, but rock art and the earliest stories show them in use.', f: 'The Māori mere, a short flat club of greenstone, was a treasured family heirloom.', p: ['club'], x: ['stone-mace'] },
  { id: 'flint-dagger', n: 'Flint dagger', c: 'blade', y: -3400, d: 'c. 3400 BCE', r: 'Europe', w: 'Late Stone Age peoples', s: 'A long, carefully flaked flint blade with a wooden or bone handle — a weapon and a status symbol.', how: 'Pressure-flaking, pressing small flakes off with an antler tip, gave a thin, sharp, even blade.', use: 'Personal defence and display. The best Danish flint daggers copied the shape of new metal daggers.', ev: 'Ötzi the Iceman carried a small flint dagger in a woven sheath.', f: 'Some Scandinavian flint daggers are so finely made that modern experts struggle to copy them.', p: ['dagger', { mat: 'stone' }], x: ['copper-axe', 'bronze-sword'] },
  { id: 'copper-axe', n: 'Copper axe', c: 'impact', y: -3300, d: 'c. 3300 BCE', r: 'Alps and the Near East', w: 'Copper Age peoples', s: 'One of the first metal weapons: an axe head of nearly pure copper set in a yew handle.', how: 'Copper was smelted from ore, cast in a mould and hammered to harden the edge.', use: 'Chopping wood and fighting. Metal was rare and valuable, so these were also signs of status.', ev: 'Ötzi the Iceman’s copper axe is the only complete prehistoric axe of its kind ever found.', f: 'Ötzi’s hands carried traces of copper, so he may have worked metal himself.', p: ['axe', { mat: 'copper' }], x: ['flint-dagger', 'bronze-sword'] },
  // ---------------- Bronze Age
  { id: 'bronze-sword', n: 'Bronze sword', c: 'blade', y: -3300, d: 'c. 3300 BCE', r: 'Anatolia (Arslantepe, Turkey)', w: 'Bronze Age smiths', s: 'The first swords: long blades cast from arsenical bronze and later tin bronze. Swords were made only for fighting people.', how: 'Molten bronze was poured into stone or clay moulds, then the edges were hammered and ground sharp.', use: 'Close combat by warriors and nobles. Early swords were short and better for thrusting than slashing.', ev: 'Swords about 5,300 years old, inlaid with silver, were found in a palace at Arslantepe in Turkey.', f: 'Bronze is about 90% copper and 10% tin; tin had to be traded from far away, so bronze weapons were costly.', p: ['sword', { mat: 'bronze', len: 'short', guard: 'none' }], x: ['khopesh', 'iron-sword'] },
  { id: 'bronze-helmet', n: 'Bronze and gold helmets', c: 'armour', y: -2500, d: 'c. 2500 BCE', r: 'Sumer (Iraq)', w: 'Sumerian kings and soldiers', s: 'Early metal helmets protected the head, the body part most often struck in battle.', how: 'Metal was hammered into a dome over a padded lining. Copper and bronze helmets were made for soldiers; gold ones for display.', use: 'The Standard of Ur shows Sumerian soldiers in helmets and cloaks marching in close ranks.', ev: 'The golden helmet of Meskalamdug, from the Royal Cemetery at Ur, was hammered from one sheet of gold.', f: 'The Ur helmet even shows hair in a bun, all shaped in the gold.', p: ['helmet', { type: 'sumer', mat: 'gold' }], x: ['corinthian-helmet'] },
  { id: 'khopesh', n: 'Khopesh (sickle sword)', c: 'blade', y: -2500, d: 'c. 2500 BCE', r: 'Mesopotamia, then Egypt and Canaan', w: 'Bronze Age armies', s: 'A curved bronze blade shaped like a question mark, sharp on the outside of the curve.', how: 'The curve puts the cutting edge forward, and the hooked tip can pull an enemy’s shield aside.', use: 'Used by Egyptian and Canaanite soldiers. It appears in many Egyptian temple carvings of pharaohs in battle.', ev: 'Two khopeshes were buried with Tutankhamun.', f: 'Its name is thought to mean “leg”, because it looks like the foreleg of an animal.', p: ['khopesh'], x: ['bronze-sword', 'chariot'] },
  { id: 'composite-bow', n: 'Composite bow', c: 'ranged', y: -2200, d: 'by c. 2200 BCE', r: 'Mesopotamia and the steppes', w: 'Akkadians and steppe peoples', s: 'A short, powerful bow made of wood, horn and sinew glued in layers. Small enough to shoot from a chariot or horse.', how: 'Horn on the belly resists squeezing, sinew on the back resists stretching, so a short bow stores far more energy than a plain wooden one.', use: 'The main weapon of chariot archers, Scythians, Huns, Mongols and Ottoman Turks for 3,000 years.', ev: 'The Victory Stele of Naram-Sin (c. 2250 BCE) shows an Akkadian king with what looks like a composite bow.', f: 'Making one could take a year, because the glue and sinew needed months to dry.', p: ['bow', { type: 'composite' }], x: ['mounted-archers', 'chariot', 'longbow'] },
  { id: 'dagger-axe', n: 'Dagger-axe (ge)', c: 'pole', y: -1900, d: 'c. 1900 BCE', r: 'China', w: 'Erlitou and Shang dynasty soldiers', s: 'A blade fixed sideways on a long pole, like a dagger turned into a pick — China’s main weapon for over 1,500 years.', how: 'Swung like a sickle, it could hook and slash at enemies or chariot crews.', use: 'The standard weapon of Chinese infantry and chariot crews until the Han dynasty.', ev: 'Thousands of bronze ge blades were buried in Shang royal tombs at Anyang.', f: 'The Chinese character for “war” (戰) contains the symbol for the ge.', p: ['polearm', { head: 'dagger-axe' }], x: ['chariot', 'crossbow-china'] },
  { id: 'chariot', n: 'War chariot', c: 'land', y: -2000, d: 'c. 2000 BCE', r: 'Russian steppes (Sintashta), then the Near East', w: 'Steppe peoples, then Hittites, Egyptians and many others', s: 'A light two-wheeled cart pulled by horses, carrying a driver and an archer or spearman. The first fast “vehicle of war”.', how: 'Spoked wheels made chariots light and fast. They carried archers along the enemy line to shoot, then wheeled away.', use: 'Chariots dominated warfare from Egypt to China between about 1700 and 1000 BCE.', ev: 'At the Battle of Kadesh in 1274 BCE, Egypt and the Hittites fought with perhaps 5,000 chariots — one of the largest chariot battles ever.', f: 'Kadesh also led to one of the first known peace treaties; a copy hangs at the United Nations in New York.', p: ['chariot'], x: ['composite-bow', 'scythed-chariot', 'stirrup'] },
  { id: 'scale-armour', n: 'Scale armour', c: 'armour', y: -1500, d: 'c. 1500 BCE', r: 'Near East (Nuzi, Egypt)', w: 'Bronze Age chariot warriors', s: 'Hundreds of small metal or leather scales sewn to a coat in overlapping rows, like the scales of a fish.', how: 'Each scale overlaps the ones below, so a blow spreads across several scales while the coat stays flexible.', use: 'Worn by chariot crews and elite soldiers across the ancient world; Romans called it lorica squamata.', ev: 'Records from Nuzi in Iraq list armour made of hundreds of bronze scales for chariot crews.', f: 'Scale armour was so valued that some ancient letters list exactly how many scales each coat needed.', p: ['armour', { type: 'scale' }], x: ['dendra-armour', 'chain-mail'] },
  { id: 'dendra-armour', n: 'Dendra bronze armour', c: 'armour', y: -1400, d: 'c. 1400 BCE', r: 'Mycenaean Greece', w: 'Mycenaean warriors', s: 'The oldest European body armour found: plates of bronze that cover the body from neck to knees.', how: 'Curved bronze plates were joined with leather straps so the wearer could move.', use: 'Probably worn by chariot warriors. In 2019 Greek marines fought for 11 hours in a copy to show it was practical.', ev: 'Found in a tomb at Dendra, near Mycenae, in 1960, with a helmet of boar’s tusks.', f: 'The helmet beside it matches Homer’s description in the Iliad of a helmet covered in boar’s tusks.', p: ['armour', { type: 'plate' }], x: ['scale-armour', 'plate-armour'] },
  { id: 'war-elephant', n: 'War elephant', c: 'land', y: -1100, d: 'by c. 1000 BCE', r: 'India', w: 'Indian kingdoms, later Persians, Carthage and Southeast Asian states', s: 'Trained elephants carried soldiers, broke enemy lines and terrified horses that had never seen them.', how: 'An elephant’s size and weight could crush a formation; archers rode on its back in a tower or howdah.', use: 'Used in India for 2,000 years, by Alexander’s enemies and successors, and by Hannibal.', ev: 'Hannibal took 37 elephants across the Alps to invade Italy in 218 BCE; very few survived.', f: 'Elephants could panic and run back into their own army, so their drivers sometimes carried a spike to stop them.', p: ['elephant'], x: ['chariot', 'caltrops'] },
  // ---------------- Iron Age & classical
  { id: 'iron-sword', n: 'Iron sword', c: 'blade', y: -1200, d: 'c. 1200 BCE', r: 'Anatolia and the Near East', w: 'Hittite and Near Eastern smiths', s: 'Iron ore is found almost everywhere, so after about 1200 BCE iron swords and spears could be made for whole armies.', how: 'Iron was heated in a furnace and hammered. Adding carbon and quenching it in water made steel, harder than bronze.', use: 'Iron weapons spread across Europe, Asia and Africa and became the normal weapons of the next 2,500 years.', ev: 'The Iron Age began as the great Bronze Age kingdoms collapsed around 1200 BCE.', f: 'Tutankhamun was buried with an iron dagger made from a meteorite — iron was still rare in his time.', p: ['sword', { mat: 'iron' }], x: ['bronze-sword', 'gladius', 'jian'] },
  { id: 'mounted-archers', n: 'Mounted archers', c: 'land', y: -800, d: 'c. 800 BCE', r: 'Eurasian steppes', w: 'Cimmerians and Scythians, later Parthians, Huns and Mongols', s: 'Riders who shot composite bows from horseback at full gallop — the most feared soldiers of the ancient world.', how: 'Riders controlled the horse with their knees and shot in any direction, then rode away before the enemy could close in.', use: 'Steppe armies of mounted archers defeated Persians, Romans, Chinese and Europeans for 2,000 years.', ev: 'At Carrhae in 53 BCE, Parthian horse archers destroyed a Roman army of about 40,000.', f: 'A “Parthian shot” — shooting backwards while riding away — gave us the phrase “a parting shot”.', p: ['horse', { rider: 1 }], x: ['composite-bow', 'stirrup', 'chariot'] },
  { id: 'battering-ram', n: 'Battering ram', c: 'siege', y: -870, d: 'c. 870 BCE', r: 'Assyria (Iraq)', w: 'Assyrian army', s: 'A heavy log, often with a metal head, swung or rolled against a gate or wall under a roof that protected the crew.', how: 'Repeated blows from a heavy beam crack stone and break wooden gates. The roof, covered in wet hides, stopped arrows and fire.', use: 'Used in sieges for 2,500 years, until cannon replaced it.', ev: 'Carvings from the palace of King Ashurnasirpal II show wheeled rams breaking city walls.', f: 'Roman law said a city that surrendered before “the ram touched the wall” could be spared.', p: ['ram'], x: ['siege-tower', 'trebuchet-counterweight', ['castle-atlas.html#gatehouse', 'Gatehouses in the Castle Atlas']] },
  { id: 'siege-tower', n: 'Siege tower', c: 'siege', y: -860, d: 'c. 860 BCE', r: 'Assyria, later Greece and Rome', w: 'Assyrian, Greek and Roman engineers', s: 'A tall wooden tower on wheels pushed up to a city wall so soldiers could cross onto the top.', how: 'Archers shot from the upper floors while a drawbridge dropped onto the wall for the attackers.', use: 'Used from Assyria to the Crusades. Defenders tried to burn them or dig holes so they toppled.', ev: 'The Helepolis (“city taker”), built for the siege of Rhodes in 305 BCE, was about 40 metres tall.', f: 'After the siege failed, the people of Rhodes sold the abandoned machines and used the money to build the Colossus of Rhodes.', p: ['siegetower'], x: ['battering-ram', ['castle-atlas.html#concentric-castle', 'Concentric castles']] },
  { id: 'trireme', n: 'Trireme', c: 'sea', y: -650, d: 'c. 7th century BCE', r: 'Mediterranean (Phoenicia, Greece)', w: 'Phoenician and Greek shipbuilders', s: 'A long, narrow warship rowed by about 170 oarsmen in three levels, with a bronze ram at the front.', how: 'The rowers drove the ship fast enough to smash its ram into an enemy ship’s side and sink it.', use: 'The main warship of the Greek and Persian wars. Athens’ navy of triremes built its empire.', ev: 'At Salamis in 480 BCE, the Greek fleet defeated the much larger Persian fleet in narrow waters.', f: 'In 1987 a full-size copy, Olympias, was built and rowed by volunteers at about 9 knots.', p: ['ship', { type: 'trireme' }], x: ['greek-fire', 'longship'] },
  { id: 'hoplite-shield', n: 'Hoplite shield (aspis)', c: 'armour', y: -700, d: 'c. 700 BCE', r: 'Greece', w: 'Greek city-states', s: 'A big, round, bowl-shaped wooden shield faced with bronze, carried on the arm by Greek citizen-soldiers called hoplites.', how: 'Each shield covered the bearer’s left side and the right side of the man next to him, so the line (phalanx) protected everyone.', use: 'The phalanx of overlapping shields and spears fought the battles of Marathon, Thermopylae and Plataea.', ev: 'At Marathon in 490 BCE, Athenian hoplites defeated a Persian invasion force.', f: 'Spartan mothers reportedly told their sons to come home “with your shield or on it”.', p: ['shield', { shape: 'round', color: '#a93226', lambda: 1 }], x: ['corinthian-helmet', 'sarissa'] },
  { id: 'corinthian-helmet', n: 'Corinthian helmet', c: 'armour', y: -700, d: 'c. 700 BCE', r: 'Greece', w: 'Greek bronze smiths', s: 'A bronze helmet beaten from one sheet, covering the whole head and face except for eye holes and a slit for the mouth.', how: 'Hammering one piece of bronze into shape left no weak joins; the face was protected but hearing and side vision were poor.', use: 'Worn by hoplites in the Persian Wars. Later, more open helmets became popular.', ev: 'Famous statues of the Athenian general Pericles show him with a Corinthian helmet pushed up on his head.', f: 'Making one from a single sheet of bronze was one of the great metalworking skills of the ancient world.', p: ['helmet', { type: 'corinthian', mat: 'bronze' }], x: ['hoplite-shield', 'bronze-helmet', 'galea'] },
  { id: 'jian', n: 'Jian (Chinese straight sword)', c: 'blade', y: -500, d: 'c. 500 BCE', r: 'China', w: 'Spring and Autumn period swordsmiths', s: 'A straight, double-edged sword, first of bronze and later of steel, prized as the “gentleman of weapons”.', how: 'Some bronze jian were made with a softer core and harder edges, so the blade was tough and sharp.', use: 'Used by Chinese soldiers and nobles; later it became mainly a weapon for martial arts and status.', ev: 'The Sword of Goujian, found in 1965, was still sharp and bright after 2,400 years in a tomb.', f: 'The Sword of Goujian’s blade is covered with a diamond pattern and an inscription naming its king.', p: ['sword', { mat: 'bronze', guard: 'cross' }], x: ['iron-sword', 'crossbow-china'] },
  { id: 'crossbow-china', n: 'Crossbow', c: 'ranged', y: -500, d: 'by c. 500 BCE', r: 'China', w: 'Warring States armies', s: 'A bow fixed across a stock, with a trigger that holds the string drawn. Easy to learn and very powerful.', how: 'A bronze trigger mechanism held the drawn string until the soldier pulled it. Soldiers could aim calmly like with a gun.', use: 'Chinese armies used tens of thousands of crossbowmen. The Terracotta Army includes many crossbowmen.', ev: 'At the Battle of Maling in 342 BCE, Qi crossbowmen ambushed and destroyed a Wei army.', f: 'Chinese crossbow triggers were made with such precise parts that they could be swapped between bows.', p: ['crossbow'], x: ['repeating-crossbow', 'crossbow-europe', 'gastraphetes'] },
  { id: 'repeating-crossbow', n: 'Repeating crossbow (zhuge nu)', c: 'ranged', y: -350, d: 'c. 4th century BCE', r: 'China', w: 'Chinese engineers; later linked with Zhuge Liang', s: 'A crossbow with a box of bolts on top. Working a lever drew the string and dropped the next bolt in place.', how: 'Pushing and pulling one lever did everything, so a soldier could shoot several bolts in a few seconds.', use: 'Weak but fast. Used to defend walls and boats, and still made in the 1890s.', ev: 'A double-shot repeating crossbow was found in a tomb of the Chu state from the 4th century BCE.', f: 'It is named after the strategist Zhuge Liang (181–234), who is said to have improved it.', p: ['crossbow', { repeat: 1 }], x: ['crossbow-china'] },
  { id: 'gastraphetes', n: 'Gastraphetes (belly bow)', c: 'siege', y: -399, d: 'c. 400 BCE', r: 'Syracuse (Sicily)', w: 'Engineers of Dionysius I', s: 'A big Greek crossbow cocked by leaning the belly against it — the ancestor of all Greek and Roman artillery.', how: 'The archer pushed his weight down on the stock to draw a bow too strong for arms alone.', use: 'Used in sieges. It led to bigger torsion catapults that shot bolts and stones.', ev: 'Dionysius I of Syracuse gathered engineers to build new weapons for his war against Carthage.', f: '“Gastraphetes” means “belly shooter” in Greek.', p: ['crossbow', { steel: 1 }], x: ['torsion-catapult', 'crossbow-china'] },
  { id: 'chain-mail', n: 'Chain mail', alt: 'Mail', c: 'armour', y: -400, d: 'c. 4th century BCE', r: 'Celtic Europe', w: 'Celtic smiths', s: 'A shirt of thousands of small iron rings linked together. Flexible, strong against cuts, and used for almost 2,000 years.', how: 'Each ring links through four others. A cut is spread over many rings, so blades cannot slice through easily.', use: 'Adopted by Romans as lorica hamata, then worn by Vikings, Normans, Crusaders and Saracens.', ev: 'Knights at the Battle of Hastings in 1066 wore long mail coats called hauberks.', f: 'A mail shirt could contain over 30,000 rings and take months to make by hand.', p: ['armour', { type: 'mail' }], x: ['scale-armour', 'plate-armour'] },
  { id: 'torsion-catapult', n: 'Torsion catapult', alt: 'Lithobolos, oxybeles', c: 'siege', y: -340, d: 'c. 340 BCE', r: 'Macedonia and Greece', w: 'Engineers of Philip II of Macedon', s: 'A war machine powered by twisted bundles of rope or sinew, throwing bolts or stones far beyond bowshot.', how: 'Twisting thick skeins of sinew stores huge energy. Released, the arms snap forward and fling the missile.', use: 'Alexander the Great used catapults to clear walls and even river banks. Romans built thousands.', ev: 'At the siege of Tyre in 332 BCE, Alexander mounted catapults on ships.', f: 'Ancient engineers worked out formulas linking the size of the skein to the weight of stone it could throw.', p: ['catapult'], x: ['ballista', 'onager', 'gastraphetes'] },
  { id: 'caltrops', n: 'Caltrops', c: 'other', y: -331, d: 'by 331 BCE', r: 'Persia, then everywhere', w: 'Persian army', s: 'Small metal spikes with four points arranged so one always points up, scattered to stop horses and soldiers.', how: 'However a caltrop lands, three points form a stand and the fourth points upward.', use: 'Used against cavalry and elephants from ancient Persia to the Second World War, and against vehicle tyres today.', ev: 'Persians scattered caltrops against Alexander’s cavalry at Gaugamela in 331 BCE.', f: 'The name comes from a spiky plant, the star thistle, called caltrop.', p: ['shuriken'], x: ['war-elephant'] },
  { id: 'sarissa', n: 'Sarissa (Macedonian pike)', c: 'pole', y: -359, d: 'c. 359 BCE', r: 'Macedonia', w: 'Philip II of Macedon', s: 'A pike 4–6 metres long, held with both hands. Rows of them made the Macedonian phalanx a wall of spear points.', how: 'The first five rows could all reach the enemy, so attackers met five spear tips before they reached a soldier.', use: 'Philip II and his son Alexander the Great conquered from Greece to India with the sarissa phalanx.', ev: 'At Gaugamela in 331 BCE, Alexander’s army defeated the much larger Persian army of Darius III.', f: 'The phalanx was strong at the front but weak at the sides; Roman legions beat it at Pydna in 168 BCE.', p: ['polearm', { head: 'sarissa' }], x: ['hoplite-shield', 'pike-square'] },
  { id: 'scythed-chariot', n: 'Scythed chariot', c: 'land', y: -401, d: 'by 401 BCE', r: 'Persian Empire', w: 'Achaemenid Persian army', s: 'A chariot with long blades fixed to the wheel hubs, driven at full speed into enemy ranks.', how: 'The blades spun with the wheels, cutting anything they passed. Only the driver rode inside.', use: 'Terrifying but easy to avoid: disciplined soldiers simply stepped aside and let it pass.', ev: 'Alexander’s men opened gaps for the scythed chariots at Gaugamela and attacked the drivers.', f: 'The Greek writer Xenophon described them at the Battle of Cunaxa in 401 BCE.', p: ['chariot', { scythe: 1, color: '#c9a227' }], x: ['chariot'] },
  { id: 'traction-trebuchet', n: 'Traction trebuchet', c: 'siege', y: -400, d: 'c. 4th century BCE', r: 'China', w: 'Mohist engineers', s: 'A big beam on a pivot with a sling at one end. A team of people pulled ropes at the short end to fling stones.', how: 'Many people pulling together whip the long arm round; the sling adds even more speed at release.', use: 'Spread from China to the Islamic world and Europe by the 7th century, then was replaced by the counterweight trebuchet.', ev: 'Avar and Byzantine armies used traction trebuchets in the siege of Thessalonica in 597.', f: 'A big one needed over 200 pullers.', p: ['trebuchet', { traction: 1 }], x: ['trebuchet-counterweight', 'torsion-catapult'] },
  { id: 'wootz-steel', n: 'Wootz and Damascus steel', c: 'blade', y: -300, d: 'c. 300 BCE', r: 'South India and Sri Lanka', w: 'Indian and Sri Lankan smiths', s: 'High-carbon steel made in small clay pots, famous for swirling patterns and tough, sharp blades.', how: 'Iron and plant material were heated together in sealed crucibles, making steel cakes that smiths forged slowly at low heat to keep the pattern.', use: 'Exported across the Middle East, where Damascus became famous for swords made from it.', ev: 'Scientists found tiny carbon nanotube-like structures in some old Damascus blades in 2006.', f: 'The way of making true wootz steel was lost in the 1800s and is still being rediscovered.', p: ['sword', { curve: .5, guard: 'swept' }], x: ['iron-sword', 'sabre'] },
  { id: 'gladius', n: 'Gladius (Roman short sword)', c: 'blade', y: -220, d: 'c. 220 BCE', r: 'Rome (copied from Spain)', w: 'Roman army', s: 'A short, straight, double-edged sword about 60 cm long, designed for stabbing from behind a large shield.', how: 'Short blades are quick in a crowded line. Legionaries punched with the shield, then stabbed.', use: 'The sword of the Roman legions that conquered the Mediterranean. Gladiators are named after it.', ev: 'Romans adopted the “Spanish sword” after fighting Celtiberian warriors in the Punic Wars.', f: 'Each legionary carried his gladius on the right side, so it did not catch on his shield when drawn.', p: ['sword', { len: 'short', wide: 1, mat: 'iron', guard: 'none' }], x: ['scutum', 'pilum', 'lorica-segmentata'] },
  { id: 'pilum', n: 'Pilum (Roman javelin)', c: 'ranged', y: -300, d: 'c. 4th–3rd century BCE', r: 'Rome', w: 'Roman army', s: 'A heavy throwing spear with a long, thin iron neck. Each legionary threw one or two just before contact.', how: 'The thin iron bent on impact, so the enemy could not throw it back, and a pilum stuck in a shield made the shield useless.', use: 'Thrown in a volley at close range to break up the enemy line just before the legion charged.', ev: 'Julius Caesar described Gauls throwing away shields pierced by several pila in his Gallic Wars.', f: 'Gaius Marius reportedly replaced one iron rivet with a wooden pin that snapped on impact.', p: ['spear', { long: 1 }], x: ['gladius', 'scutum'] },
  { id: 'scutum', n: 'Scutum (Roman shield)', c: 'armour', y: -300, d: 'c. 4th century BCE', r: 'Rome', w: 'Roman army', s: 'A tall, curved, rectangular shield of glued wood layers covered in leather, with a metal boss in the centre.', how: 'Its curve wrapped round the body. Soldiers could lock shields together into a “tortoise” (testudo).', use: 'In the testudo, front rows held shields forward and others held them overhead, protecting the group from arrows and stones.', ev: 'The only nearly complete scutum found comes from Dura-Europos in Syria, about 250 CE.', f: 'It weighed about 10 kg — soldiers trained with double-weight shields.', p: ['shield', { shape: 'scutum', color: '#a93226' }], x: ['gladius', 'pilum', 'lorica-segmentata'] },
  { id: 'ballista', n: 'Ballista and scorpio', c: 'siege', y: -100, d: '1st century BCE', r: 'Roman Republic', w: 'Roman engineers (based on Greek designs)', s: 'Roman bolt-throwers, like giant crossbows powered by twisted sinew, accurate enough to hit a single soldier.', how: 'Two arms set in twisted skeins of sinew drove a heavy bolt along a track with great force.', use: 'Each legion had dozens. They were used in sieges and on the battlefield, like early field artillery.', ev: 'Julius Caesar used them at Alesia in 52 BCE; a Gallic warrior was hit by a bolt on the walls.', f: 'A small scorpio could shoot a bolt about 300 metres.', p: ['ballista'], x: ['torsion-catapult', 'onager'] },
  { id: 'lorica-segmentata', n: 'Lorica segmentata', c: 'armour', y: -9, d: 'by 9 BCE', r: 'Roman Empire', w: 'Roman army', s: 'Roman armour of overlapping iron bands fastened with hooks and leather straps, covering the chest, back and shoulders.', how: 'Hinged bands slide over each other, so the wearer can bend while staying covered by iron.', use: 'Worn by legionaries in the 1st and 2nd centuries CE. It is the armour most people picture on Romans.', ev: 'Pieces were found at Kalkriese in Germany, site of the Teutoburg Forest defeat in 9 CE.', f: 'The Latin name was made up by scholars in the 1500s; we don’t know what Romans called it.', p: ['armour', { type: 'plate' }], x: ['scutum', 'gladius', 'galea'] },
  { id: 'galea', n: 'Roman helmet (galea)', c: 'armour', y: 10, d: '1st century CE', r: 'Roman Empire', w: 'Roman army', s: 'An iron or bronze helmet with cheek guards and a wide neck guard, sometimes with a crest for officers.', how: 'The neck guard sloped out to deflect blows to the back of the neck; cheek guards left the ears and eyes free.', use: 'Worn by legionaries across the empire, from Britain to Syria.', ev: 'Centurions wore crests from side to side so their men could find them in battle.', f: 'Soldiers often scratched their names on their helmets, so we know some owners.', p: ['helmet', { type: 'galea' }], x: ['corinthian-helmet', 'lorica-segmentata'] },
  { id: 'stirrup', n: 'Stirrup', c: 'land', y: 322, d: 'c. 322 CE', r: 'China', w: 'Jin dynasty horsemen', s: 'Loops hanging from the saddle for the rider’s feet. They made riders far steadier in the saddle.', how: 'With feet braced in stirrups, a rider can stand, lean and strike hard without being knocked off.', use: 'Spread across Asia to Europe by the 700s and helped make heavy cavalry and knights possible.', ev: 'A pottery figure of a rider with stirrups from a tomb near Nanjing dates to about 322 CE.', f: 'Historians still argue how much the stirrup changed medieval society — a debate called “the Great Stirrup Controversy”.', p: ['horse', { stirrup: 1 }], x: ['mounted-archers', 'couched-lance'] },
  { id: 'onager', n: 'Onager', c: 'siege', y: 353, d: '4th century CE', r: 'Roman Empire', w: 'Late Roman army', s: 'A one-armed catapult powered by a twisted rope bundle, flinging stones from a sling or cup.', how: 'The arm was pulled down against the twisted rope, then released to swing up and hit a padded beam.', use: 'Used by the late Roman army and the Byzantines to batter walls and defend cities.', ev: 'The historian Ammianus Marcellinus described it in the 4th century.', f: 'It was named after the wild donkey (onager), because it “kicked” stones.', p: ['catapult'], x: ['torsion-catapult', 'traction-trebuchet'] },
  // ---------------- Middle Ages
  { id: 'greek-fire', n: 'Greek fire', c: 'other', y: 672, d: '672', r: 'Byzantine Empire', w: 'Kallinikos, a refugee from Syria', s: 'A secret liquid fire sprayed from tubes on Byzantine ships. It kept burning even on water.', how: 'Its recipe is lost. It was probably based on crude oil, heated and pumped through a bronze tube called a siphon.', use: 'It helped Constantinople defeat Arab fleets in 674–678 and 717–718 and the Rus’ in 941.', ev: 'The formula was a state secret known only to a few families, and it was eventually forgotten.', f: 'Historians still don’t know exactly what was in it.', p: ['greekfire'], x: ['trireme', 'flamethrower'] },
  { id: 'longship', n: 'Viking longship', c: 'sea', y: 793, d: '793', r: 'Scandinavia', w: 'Norse shipbuilders', s: 'A long, light ship with oars and a square sail and a shallow hull. It could cross the sea and row up rivers.', how: 'Overlapping planks (clinker building) made a flexible, light hull that rode the waves and could be beached.', use: 'Vikings raided and traded from North America to Baghdad, attacking coasts and river towns.', ev: 'The Viking Age is usually dated from the raid on Lindisfarne monastery, England, in 793.', f: 'Viking ships were so light that crews sometimes carried them overland between rivers.', p: ['ship', { type: 'longship' }], x: ['viking-sword', 'dane-axe'] },
  { id: 'viking-sword', n: 'Viking sword', alt: 'Ulfberht sword', c: 'blade', y: 800, d: '9th century', r: 'Northern Europe', w: 'Frankish and Norse smiths', s: 'A straight, double-edged sword with a short guard and a heavy pommel, often passed down as an heirloom.', how: 'The best blades were made of high-quality steel; the heavy pommel balanced the blade for one-handed fighting.', use: 'Carried by richer Viking warriors with a round wooden shield; most fighters had spears and axes.', ev: 'About 170 swords marked +VLFBERHT are known. Some are made of very pure steel, rare in Europe then.', f: 'Viking swords were given names, like Leg-biter.', p: ['sword', { guard: 'cross', mat: 'iron' }], x: ['longship', 'dane-axe', 'kite-shield'] },
  { id: 'sabre', n: 'Sabre', alt: 'Turko-Mongol sabre, scimitar', c: 'blade', y: 900, d: 'c. 9th–10th century', r: 'Central Asia and Eastern Europe', w: 'Turkic and Magyar horsemen', s: 'A curved, single-edged sword for slashing from horseback.', how: 'The curve makes the blade slide as it cuts, giving a long slicing cut at speed.', use: 'Used by horsemen from Persia and the Ottoman Empire to Polish hussars and Napoleon’s cavalry.', ev: 'Persian shamshirs and Ottoman kilijs became famous across the world.', f: 'Cavalry sabres were still carried in the First World War.', p: ['sword', { curve: .6, guard: 'swept' }], x: ['katana', 'mounted-archers'] },
  { id: 'dane-axe', n: 'Dane axe', c: 'impact', y: 900, d: 'c. 10th century', r: 'Scandinavia, England', w: 'Viking and Anglo-Saxon warriors', s: 'A big, thin-bladed axe on a long handle, swung with two hands.', how: 'A long handle gives a fast, powerful swing; the thin, wide blade cuts deeply.', use: 'Carried by Viking warriors and the Anglo-Saxon royal guard, the housecarls.', ev: 'The Bayeux Tapestry shows English housecarls swinging Dane axes at Hastings in 1066.', f: 'The Varangian Guard — Viking bodyguards of the Byzantine emperor — were called “axe-bearing barbarians”.', p: ['axe', { long: 1 }], x: ['viking-sword', 'halberd'] },
  { id: 'katana', n: 'Japanese sword (tachi and katana)', c: 'blade', y: 950, d: 'c. 10th century', r: 'Japan', w: 'Japanese swordsmiths', s: 'A curved, single-edged sword with a very hard edge and a softer back, carried by samurai.', how: 'Smiths folded and hammered steel, then coated the blade in clay before quenching. The thin-coated edge cooled fast and became very hard; the curve formed as it cooled.', use: 'Samurai carried the longer tachi, edge down, on horseback; from the 1400s the katana was worn edge up for a fast draw.', ev: 'Masamune, who worked around 1300, is often called Japan’s greatest swordsmith.', f: 'The wavy line on the blade (hamon) shows where the hard edge meets the softer steel.', p: ['sword', { curve: .35, guard: 'disc', two: 1 }], x: ['samurai-armour', 'naginata', 'sabre'] },
  { id: 'fire-lance', n: 'Fire lance', c: 'gun', y: 950, d: 'c. 10th century', r: 'China', w: 'Song dynasty soldiers', s: 'A bamboo or paper tube of gunpowder tied to a spear. When lit, it shot out flame and bits of shrapnel — the ancestor of the gun.', how: 'Burning gunpowder in a tube pushes out flames and anything put in front of it.', use: 'Used at close range in sieges. Later metal tubes turned it into the first real guns.', ev: 'A Buddhist painting from Dunhuang of about 950 shows a demon holding a fire lance.', f: 'Each fire lance worked for only a few seconds.', p: ['firearrow'], x: ['gunpowder', 'hand-cannon'] },
  { id: 'gunpowder', n: 'Gunpowder', alt: 'Black powder', c: 'boom', y: 850, d: 'c. 850', r: 'China', w: 'Chinese alchemists', s: 'A mix of saltpetre, charcoal and sulfur that burns very fast. Its discovery led to fireworks, rockets, guns and cannon.', how: 'Saltpetre releases oxygen as it burns, so the mixture burns fast even inside a closed tube.', use: 'First used in fire arrows and bombs, then guns. It reached the Islamic world and Europe in the 1200s.', ev: 'The Wujing Zongyao, a Chinese military book of 1044, gives the oldest known written recipes.', f: 'Alchemists found it while looking for an elixir of eternal life.', p: ['grenade', { type: 'ceramic' }], x: ['fire-lance', 'thunderclap-bomb', 'fire-arrow', ['invention-atlas.html#gunpowder', 'Gunpowder in the Invention Atlas']] },
  { id: 'kite-shield', n: 'Kite shield', c: 'armour', y: 1000, d: 'c. 1000', r: 'Western Europe', w: 'Norman and Byzantine knights', s: 'A long shield, round at the top and pointed at the bottom, protecting a rider’s leg as well as body.', how: 'The long tail covered the left leg of a mounted knight, which a round shield could not.', use: 'Carried by Normans and early Crusaders; it later shrank into the smaller heater shield.', ev: 'The Bayeux Tapestry shows Norman knights with kite shields at Hastings in 1066.', f: 'Painted designs on shields helped knights recognise each other and grew into heraldry.', p: ['shield', { shape: 'kite', color: '#2b5a8a' }], x: ['great-helm', 'couched-lance', 'chain-mail'] },
  { id: 'crossbow-europe', n: 'Medieval crossbow', c: 'ranged', y: 1000, d: 'c. 10th century (Europe)', r: 'Europe', w: 'Medieval armies', s: 'A crossbow strong enough to pierce mail. Later ones had steel bows drawn with winches.', how: 'A crank or lever drew a bow far stronger than any archer could, and a trigger held it ready.', use: 'Used in sieges and battles, and by Genoese mercenaries. Easy to learn compared with a longbow.', ev: 'In 1139 the Church banned crossbows for use against Christians — a ban that was widely ignored.', f: 'Richard the Lionheart was killed by a crossbow bolt in 1199.', p: ['crossbow', { steel: 1 }], x: ['crossbow-china', 'longbow', 'pavise'] },
  { id: 'couched-lance', n: 'Couched lance', c: 'pole', y: 1050, d: '11th century', r: 'Western Europe', w: 'Norman and Frankish knights', s: 'A long spear held tightly under the arm by a charging knight, so the whole weight of horse and rider hit the target.', how: 'Stirrups and a high saddle let the knight brace himself, so the horse’s speed went into the lance tip.', use: 'The charge of armoured knights was the most powerful attack in Europe for 300 years.', ev: 'Byzantine princess Anna Komnene wrote that a Frankish charge “could make a hole in the walls of Babylon”.', f: 'Tournaments and jousting grew out of training for the couched-lance charge.', p: ['polearm', { head: 'lance' }], x: ['stirrup', 'kite-shield', 'plate-armour'] },
  { id: 'flanged-mace', n: 'Flanged mace', c: 'impact', y: 1100, d: '12th century', r: 'Persia, Byzantium, Europe', w: 'Medieval armourers', s: 'A metal club whose head has raised ridges (flanges) that could dent or break through armour.', how: 'The flanges focus the force of a blow on a small area, which can crush armour and the bones beneath.', use: 'Popular when knights wore heavier armour that swords could not cut.', ev: 'Maces became symbols of command; the British parliament’s mace is a descendant.', f: 'A story says bishops used maces so they would not “shed blood” — historians think this is a myth.', p: ['mace', { type: 'flanged' }], x: ['stone-mace', 'flail', 'war-hammer'] },
  { id: 'samurai-armour', n: 'Samurai armour (ō-yoroi)', c: 'armour', y: 1100, d: '12th century', r: 'Japan', w: 'Japanese armourers', s: 'Box-like armour of small lacquered iron and leather scales laced together with coloured silk cords, worn by mounted samurai archers.', how: 'Rows of small plates (lamellae) were lacquered against rust and laced together, making armour that was strong but flexible.', use: 'Made for horse archers in the Genpei War (1180–1185). Later, lighter armour suited fighting on foot.', ev: 'Many beautiful suits survive in Japanese shrines, given as offerings by samurai.', f: 'The colours of the lacing could show which family or side a samurai belonged to.', p: ['helmet', { type: 'kabuto' }], x: ['katana', 'naginata', 'scale-armour'] },
  { id: 'naginata', n: 'Naginata', c: 'pole', y: 1150, d: 'Heian period (12th century)', r: 'Japan', w: 'Japanese warrior monks and samurai', s: 'A long pole with a curved, sword-like blade, good for sweeping cuts against riders and horses.', how: 'Its long reach and curved blade let the user cut at legs and horses from a distance.', use: 'Used by samurai and warrior monks; later it became the traditional weapon of samurai women.', ev: 'The warrior monk Benkei, famous in Japanese legend, is often shown with a naginata.', f: 'Naginata is still a martial art in Japan today.', p: ['polearm', { head: 'glaive' }], x: ['katana', 'halberd'] },
  { id: 'trebuchet-counterweight', n: 'Counterweight trebuchet', c: 'siege', y: 1165, d: 'c. 1165', r: 'Mediterranean (Byzantium and the Islamic world)', w: 'Byzantine and Arab engineers', s: 'A huge siege machine where a falling box of earth or stones swings a long arm and flings a boulder from a sling.', how: 'A heavy counterweight falls and swings the long arm upward; the sling adds speed, like a whip. Gravity did the work of hundreds of pullers.', use: 'The most powerful siege weapon before cannon. It could throw stones of over 100 kg to break castle walls.', ev: 'Edward I built a giant one, “Warwolf”, at the siege of Stirling Castle in 1304 — the Scots tried to surrender before it fired.', f: 'Edward refused the surrender until he had seen Warwolf work.', p: ['trebuchet'], x: ['traction-trebuchet', 'bombard', ['castle-atlas.html#concentric-castle', 'Concentric castles']] },
  { id: 'great-helm', n: 'Great helm', c: 'armour', y: 1200, d: 'c. 1200', r: 'Western Europe', w: 'Crusader-era knights', s: 'A flat-topped, bucket-shaped helmet covering the whole head, with narrow eye slits and breathing holes.', how: 'A closed helmet protected the face from arrows and lances, but it was hot and hard to see out of.', use: 'Worn by knights in the Crusades and wars of the 13th century, often over a mail hood.', ev: 'Knights painted their helmets or added crests so they could be recognised in battle.', f: 'Many knights took it off as soon as the charge was over, because they could hardly see or breathe.', p: ['helmet', { type: 'great' }], x: ['kite-shield', 'plate-armour'] },
  { id: 'thunderclap-bomb', n: 'Iron bomb (thunderclap bomb)', c: 'boom', y: 1221, d: '1221', r: 'China', w: 'Jin dynasty defenders', s: 'Gunpowder sealed in an iron case that burst into fragments — the first true exploding bombs.', how: 'Gunpowder in a closed iron shell burns until the pressure bursts the case.', use: 'Thrown by trebuchets and by hand in sieges between the Jin, Song and Mongols.', ev: 'Bombs were used against the Mongols at the siege of Kaifeng in 1232.', f: 'Ceramic bombs from a Mongol shipwreck of 1281 were found off Japan.', p: ['grenade', { type: 'round' }], x: ['gunpowder', 'hand-grenade'] },
  { id: 'fire-arrow', n: 'Gunpowder rocket (fire arrow)', c: 'art', y: 1232, d: '1232', r: 'China', w: 'Jin and Song dynasty armies', s: 'An arrow with a tube of gunpowder tied to it. The burning powder pushed it forward — the first rockets.', how: 'Gas from burning powder rushes out of the back of the tube, pushing the rocket forward.', use: 'Fired in large numbers from racks. They were inaccurate but frightening.', ev: 'At the siege of Kaifeng in 1232, defenders used “arrows of flying fire” against the Mongols.', f: 'Every space rocket works by the same principle as these first fire arrows.', p: ['firearrow'], x: ['gunpowder', 'hwacha', 'mysorean-rockets', ['space-atlas.html#goddard-rocket', 'Rockets in the Space Atlas']] },
  { id: 'longbow', n: 'English longbow', c: 'ranged', y: 1280, d: '13th century', r: 'Wales and England', w: 'Welsh and English archers', s: 'A bow as tall as a man, usually of yew. Trained archers could shoot 10 or more arrows a minute.', how: 'Yew has springy sapwood on the back and hard heartwood on the belly, a natural “composite” that stores lots of energy.', use: 'Massed English archers won victories in the Hundred Years’ War. Training began in childhood.', ev: 'At Agincourt in 1415, English archers helped a small army defeat a much larger French one.', f: 'English law once required men to practise archery on Sundays.', p: ['bow', { type: 'long' }], x: ['crossbow-europe', 'bow-arrow', 'plate-armour'] },
  { id: 'hand-cannon', n: 'Hand cannon', alt: 'Handgonne', c: 'gun', y: 1288, d: 'c. 1288', r: 'China', w: 'Yuan dynasty soldiers', s: 'A small metal tube on a pole, loaded with powder and a ball and lit by hand — the first true handheld gun.', how: 'Burning powder in a closed metal barrel pushes the ball out. The shooter held the pole under one arm and lit the touch hole.', use: 'Spread to Europe and the Middle East in the 1300s. Hard to aim, but it could pierce armour.', ev: 'The Heilongjiang hand cannon, found in northeast China, dates to about 1288.', f: 'Early hand cannons were so inaccurate that they were mostly fired at large groups.', p: ['gun', { type: 'handgonne' }], x: ['fire-lance', 'matchlock'] },
  { id: 'pavise', n: 'Pavise', c: 'armour', y: 1350, d: '14th century', r: 'Italy and Central Europe', w: 'Crossbowmen of Genoa and Bohemia', s: 'A tall shield that a crossbowman stood behind while he reloaded.', how: 'A spike or prop held the pavise upright on the ground, so both hands were free to wind the crossbow.', use: 'Used by crossbowmen in sieges and battles, often carried by a helper.', ev: 'At Crécy in 1346, Genoese crossbowmen were sent forward without their pavises, which were still with the baggage.', f: 'Pavises were often painted with the town’s coat of arms or a saint.', p: ['shield', { shape: 'pavise', color: '#2b5a8a' }], x: ['crossbow-europe', 'longbow'] },
  { id: 'halberd', n: 'Halberd', c: 'pole', y: 1300, d: 'c. 14th century', r: 'Switzerland and Germany', w: 'Swiss infantry', s: 'An axe blade topped with a spike on a long pole, with a hook on the back — three weapons in one.', how: 'The spike kept riders back, the axe could cut through armour, and the hook could pull a knight off his horse.', use: 'Swiss foot soldiers used halberds to defeat armoured knights.', ev: 'At Morgarten in 1315, Swiss fighters with halberds ambushed and beat an Austrian army.', f: 'The Swiss Guard at the Vatican still carry halberds.', p: ['polearm', { head: 'halberd' }], x: ['pike-square', 'dane-axe'] },
  { id: 'flail', n: 'Flail and morning star', c: 'impact', y: 1300, d: '14th century', r: 'Europe', w: 'Medieval soldiers and peasants', s: 'A spiked ball (morning star) on a handle, or a spiked head joined to the handle by a chain (flail).', how: 'On a chain, the head swings around a shield’s edge. Spikes focus the force on a small point.', use: 'Military flails were rare; farm flails for threshing grain were sometimes used as weapons.', ev: 'Hussite rebels in Bohemia in the 1420s fought with farm flails from their war wagons.', f: 'Historians think chain flails were much rarer in real battles than in films and games.', p: ['mace', { type: 'flail' }], x: ['flanged-mace', 'war-wagon'] },
  { id: 'cannon', n: 'Cannon', c: 'art', y: 1326, d: '1326', r: 'Europe (first picture), after China', w: 'European gunfounders', s: 'A big metal tube that fires a heavy ball with gunpowder — the weapon that ended the age of castles.', how: 'Powder is packed at the closed end, a ball in front, and fire through a small touch hole sets it off.', use: 'First used in sieges and at battles like Crécy (1346). Within 150 years, cannon could break any medieval wall.', ev: 'The oldest European picture of a cannon is in Walter de Milemete’s manuscript of 1326.', f: 'Early cannon looked like vases and fired arrows as well as stones.', p: ['cannon', { type: 'field' }], x: ['bombard', 'field-artillery', 'hand-cannon'] },
  { id: 'plate-armour', n: 'Full plate armour', c: 'armour', y: 1400, d: 'c. 1400', r: 'Italy and Germany', w: 'Armourers of Milan and Nuremberg', s: 'A suit of shaped steel plates covering the whole body. Much lighter and more flexible than most people imagine.', how: 'Curved plates make blows glance off; sliding joints let the wearer run, climb and roll.', use: 'Worn by knights and men-at-arms in the 1400s and 1500s. Good guns made it too heavy to be worth it.', ev: 'A full suit weighed 20–25 kg, spread across the whole body — less than a modern soldier’s pack.', f: 'Experiments show a knight in armour could climb a ladder and get up from the ground easily.', p: ['armour', { type: 'plate' }], x: ['chain-mail', 'war-hammer', 'longbow'] },
  { id: 'pike-square', n: 'Pike square', c: 'pole', y: 1400, d: '15th century', r: 'Switzerland, later all Europe', w: 'Swiss and German soldiers (Landsknechte)', s: 'Blocks of hundreds of soldiers with 5-metre pikes, bristling in all directions, that cavalry could not break.', how: 'Pikes kept horses at a distance; drilling let the block march and turn together.', use: 'Pike blocks, later mixed with musketeers (“pike and shot”), ruled European battlefields until about 1700.', ev: 'Swiss pikemen destroyed the army of Charles the Bold of Burgundy at Grandson and Murten in 1476.', f: 'The bayonet made pikes unnecessary, because every musket could become a short pike.', p: ['polearm', { head: 'pike' }], x: ['sarissa', 'halberd', 'bayonet'] },
  { id: 'war-hammer', n: 'War hammer', c: 'impact', y: 1400, d: '15th century', r: 'Europe', w: 'Knights and men-at-arms', s: 'A hammer with a spike on the back, made to beat or pierce plate armour.', how: 'The spike could punch through armour; the hammer face stunned through a helmet.', use: 'Popular when plate armour made swords less useful. Some had long handles (pollaxes).', ev: 'Fighting manuals of the 1400s show knights in armour fighting with pollaxes.', f: 'The Polish horseman’s hammer called the nadziak was used into the 1700s.', p: ['mace', { type: 'hammer' }], x: ['plate-armour', 'flanged-mace'] },
  { id: 'war-wagon', n: 'Hussite war wagon', c: 'land', y: 1420, d: '1420', r: 'Bohemia (Czech Republic)', w: 'Jan Žižka and the Hussites', s: 'Farm wagons chained together into a mobile fort, with guns and crossbows firing through gaps.', how: 'Wagons in a ring made a wall the enemy cavalry could not break; then the defenders counter-attacked.', use: 'Peasant Hussite armies defeated several crusades sent against them in the 1420s and 1430s.', ev: 'The Czech word for their guns, píšťala (“pipe”), may be where the word “pistol” comes from.', f: 'Žižka won many battles even after losing both eyes.', p: ['e', '🛞'], x: ['flail', 'hand-cannon', 'tank-mark-i'] },
  { id: 'bombard', n: 'Bombard (siege cannon)', c: 'art', y: 1450, d: '15th century', r: 'Europe and the Ottoman Empire', w: 'Gunfounders such as Orban', s: 'Gigantic cannon that fired stone balls weighing hundreds of kilos to smash fortress walls.', how: 'A huge barrel of bronze or iron hoops fired heavy balls slowly — sometimes only a few shots a day.', use: 'Ended the medieval castle. Kings with big guns could take any town.', ev: 'Sultan Mehmed II’s great cannon, cast by Orban, battered the walls of Constantinople in 1453.', f: 'The Dardanelles Gun of 1464 weighs 17 tonnes; it is now at Fort Nelson in England.', p: ['cannon', { type: 'bombard' }], x: ['cannon', 'trebuchet-counterweight', ['castle-atlas.html#theodosian-walls', 'The walls of Constantinople']] },
  { id: 'mortar', n: 'Mortar', c: 'art', y: 1450, d: '15th century', r: 'Europe and the Ottoman Empire', w: 'European and Ottoman gunners', s: 'A short, fat cannon that fires bombs high into the air so they drop over walls.', how: 'A steep angle sends the shot up and over; later mortars fired hollow exploding shells.', use: 'Used in sieges from the 1400s to today; infantry still carry small mortars.', ev: 'Mortars were used at the siege of Constantinople in 1453.', f: 'Its name comes from the bowl used to grind spices, which it looks like.', p: ['cannon', { type: 'mortar' }], x: ['bombard', 'hand-grenade'] },
  // ---------------- Gunpowder age
  { id: 'hwacha', n: 'Hwacha', c: 'art', y: 1451, d: '1451', r: 'Korea', w: 'Joseon dynasty, King Munjong', s: 'A cart that launched up to 100 gunpowder rocket-arrows at once.', how: 'Rocket-arrows were fitted in a wooden block on a two-wheeled cart, and a single fuse set them off in sequence.', use: 'Used to defend fortresses and against Japanese invasions.', ev: 'At the Battle of Haengju in 1593, Korean defenders with hwachas helped defeat a much larger Japanese army.', f: 'Hwacha means “fire cart”.', p: ['e', '🎆'], x: ['fire-arrow', 'turtle-ship', 'katyusha'] },
  { id: 'matchlock', n: 'Matchlock arquebus', c: 'gun', y: 1475, d: 'c. 1475', r: 'Europe', w: 'European gunsmiths', s: 'The first gun with a trigger. A smouldering cord (the match) was lowered into the powder pan when the trigger was pulled.', how: 'Pulling the trigger swung an S-shaped arm holding the glowing match into a pan of fine powder, firing the gun.', use: 'It let soldiers aim with both hands. Arquebusiers and pikemen fought side by side.', ev: 'At Nagashino in 1575, Oda Nobunaga’s arquebusiers, firing in turns, defeated the Takeda cavalry.', f: 'A lit match glows at night and smells, so it was hard to hide an ambush.', p: ['gun', { type: 'matchlock' }], x: ['hand-cannon', 'musket', 'wheellock'] },
  { id: 'rifling', n: 'Rifled barrel', c: 'gun', y: 1500, d: 'c. 1500', r: 'Germany (Augsburg, Nuremberg)', w: 'German gunsmiths', s: 'Spiral grooves cut inside a gun barrel make the bullet spin, so it flies far straighter.', how: 'A spinning bullet is stable, like a spinning top or a well-thrown football.', use: 'Rifles were slow to load until the 1800s, so at first only hunters and sharpshooters used them.', ev: 'American riflemen picked off British officers at Saratoga in 1777.', f: 'The word “rifle” comes from an old word meaning “to groove”.', p: ['gun', { type: 'rifle' }], x: ['minie-ball', 'musket'] },
  { id: 'rapier', n: 'Rapier', c: 'blade', y: 1500, d: 'c. 1500', r: 'Spain and Italy', w: 'Spanish and Italian swordsmiths', s: 'A long, slim sword for thrusting, with an elaborate guard to protect the hand.', how: 'A thin, stiff blade makes fast thrusts at long reach; swept bars or a cup guard the hand.', use: 'Worn by gentlemen as part of everyday clothes and used in duels more than in war.', ev: 'Fencing schools in Italy and Spain wrote books on rapier fighting with geometry and diagrams.', f: 'Modern sport fencing descends from rapier and smallsword fighting.', p: ['sword', { guard: 'basket', len: 'long', rot: -20 }], x: ['zweihander', 'sabre'] },
  { id: 'zweihander', n: 'Zweihänder (two-handed sword)', c: 'blade', y: 1500, d: '16th century', r: 'Germany and Switzerland', w: 'Landsknecht mercenaries', s: 'A huge sword up to 1.8 metres long, swung with both hands.', how: 'A second short guard on the blade let the soldier grip it higher for close fighting.', use: 'Elite “double-pay” soldiers used it to break into pike formations.', ev: 'Landsknechte carrying two-handed swords guarded their banners in battle.', f: 'Many surviving huge swords were for parades only.', p: ['sword', { len: 'long', two: 1, guard: 'cross', rot: -12 }], x: ['rapier', 'pike-square'] },
  { id: 'wheellock', n: 'Wheellock', c: 'gun', y: 1505, d: 'c. 1505', r: 'Germany and Italy', w: 'German gunsmiths (an idea also sketched by Leonardo da Vinci)', s: 'A gun lit by sparks from a spinning steel wheel rubbing on a mineral, like a modern lighter. No burning match needed.', how: 'A wound-up spring spun a rough steel wheel against iron pyrite, throwing sparks into the powder.', use: 'Expensive, so used for hunting and cavalry pistols. Mounted soldiers could carry loaded guns.', ev: 'Cavalry called reiters fired wheellock pistols at enemy lines in the 1500s.', f: 'Leonardo da Vinci drew a wheellock mechanism around 1500.', p: ['gun', { type: 'wheellock' }], x: ['matchlock', 'flintlock', 'pistol'] },
  { id: 'musket', n: 'Musket', c: 'gun', y: 1521, d: '1520s', r: 'Spain', w: 'Spanish army', s: 'A heavier gun than the arquebus, firing a bigger ball that could pierce plate armour.', how: 'Early muskets were so heavy they were rested on a forked stick. Later ones were lighter and fired from the shoulder.', use: 'Muskets and later flintlocks were the main infantry weapon for 300 years.', ev: 'Spanish arquebusiers helped win the Battle of Pavia in 1525, capturing the French king.', f: 'Musketeers could fire about two or three shots a minute.', p: ['gun', { type: 'musket', ramrod: 1 }], x: ['matchlock', 'flintlock', 'bayonet'] },
  { id: 'galleon', n: 'Galleon', c: 'sea', y: 1540, d: '16th century', r: 'Spain and Portugal', w: 'Iberian shipbuilders', s: 'A big sailing ship with several masts, high decks and rows of cannon, built for war and long ocean trade.', how: 'Square and triangular sails let it cross oceans; cannon fired through gunports in the sides.', use: 'Spanish treasure fleets carried silver from the Americas. Galleons fought for control of the seas.', ev: 'The Spanish Armada of 1588 failed to invade England after battles and storms.', f: 'The Mary Rose, a warship that sank in 1545, was raised in 1982 and can be seen in Portsmouth.', p: ['ship', { type: 'galleon' }], x: ['ship-of-the-line', 'turtle-ship'] },
  { id: 'pistol', n: 'Pistol', c: 'gun', y: 1540, d: '1540s', r: 'Germany', w: 'German gunsmiths', s: 'A small gun fired with one hand, first for cavalry and later for personal protection.', how: 'Wheellocks, then flintlocks, let a rider carry a loaded gun ready to fire.', use: 'Cavalry carried two or more. Later, officers, sailors and duellists used them.', ev: 'Duels with pistols were common in the 1700s and early 1800s.', f: 'US Treasury Secretary Alexander Hamilton was killed in a pistol duel in 1804.', p: ['gun', { type: 'pistol' }], x: ['wheellock', 'revolver'] },
  { id: 'turtle-ship', n: 'Turtle ship (geobukseon)', c: 'sea', y: 1592, d: '1592', r: 'Korea', w: 'Admiral Yi Sun-sin', s: 'A Korean warship with a covered, spiked roof, cannon on all sides and a dragon head at the front.', how: 'The roof stopped enemies from climbing aboard, and many cannon fired from protected ports.', use: 'Admiral Yi’s fleet with turtle ships won battle after battle against Japanese invasion fleets.', ev: 'At Myeongnyang in 1597, Yi won with 13 ships against more than 130.', f: 'Some accounts say the dragon head could breathe smoke to hide the ship.', p: ['ship', { type: 'turtle' }], x: ['hwacha', 'galleon', 'ironclad'] },
  { id: 'flintlock', n: 'Flintlock', c: 'gun', y: 1610, d: 'c. 1610', r: 'France', w: 'Marin le Bourgeoys', s: 'A gun lit by a flint striking steel. Cheaper than the wheellock and safer than the match.', how: 'Pulling the trigger snapped a flint against a steel plate, throwing sparks into the powder pan.', use: 'The standard soldier’s gun from about 1700 to 1840, from the Brown Bess to the American Revolution.', ev: 'Napoleon’s armies and Wellington’s at Waterloo (1815) fought with flintlock muskets.', f: '“Flash in the pan” comes from when only the pan powder burned and the gun didn’t fire.', p: ['gun', { type: 'flintlock' }], x: ['wheellock', 'percussion-cap', 'bayonet'] },
  { id: 'field-artillery', n: 'Light field artillery', c: 'art', y: 1630, d: '1630s', r: 'Sweden', w: 'King Gustavus Adolphus', s: 'Lighter cannon on wheels that moved with the army and fired during the battle.', how: 'Standard sizes and ready-made cartridges let crews fire faster and keep the guns supplied.', use: 'Gustavus Adolphus’s mobile guns helped Sweden win the Thirty Years’ War battles.', ev: 'At Breitenfeld in 1631, Swedish guns fired about three times faster than their enemies’.', f: 'Napoleon trained as an artillery officer and called artillery “the god of war”.', p: ['cannon', { type: 'field' }], x: ['cannon', 'quick-firing-gun'] },
  { id: 'bayonet', n: 'Bayonet', c: 'blade', y: 1640, d: '1640s', r: 'France (Bayonne)', w: 'French soldiers', s: 'A blade fixed to the end of a musket, turning every musketeer into a pikeman.', how: 'Early plug bayonets blocked the barrel; socket bayonets of the 1680s fitted around it so the gun could still fire.', use: 'Pikes disappeared by about 1700. Bayonets are still issued to many soldiers.', ev: 'Bayonet charges were common in battles from the 1700s to the First World War.', f: 'It is probably named after Bayonne, in south-west France.', p: ['gun', { type: 'musket', bayonet: 1 }], x: ['pike-square', 'musket'] },
  { id: 'ship-of-the-line', n: 'Ship of the line', c: 'sea', y: 1650, d: '17th century', r: 'England, Netherlands, France', w: 'European navies', s: 'A big wooden warship with two or three decks of cannon, built to fight in a long line with other ships.', how: 'Ships sailed in a line so each could fire its whole side (a broadside) at the enemy.', use: 'The battleships of the age of sail, from the 1650s to the 1850s.', ev: 'At Trafalgar in 1805, Nelson’s fleet broke the French-Spanish line; his flagship HMS Victory still survives.', f: 'HMS Victory carried 104 guns and about 820 sailors.', p: ['ship', { type: 'shipofline' }], x: ['galleon', 'ironclad'] },
  { id: 'hand-grenade', n: 'Hand grenade', c: 'boom', y: 1660, d: '17th century (Europe)', r: 'Europe, after China', w: 'European armies', s: 'A small bomb thrown by hand. Special tall soldiers called grenadiers were trained to throw them.', how: 'Early grenades were iron balls of powder with a fuse lit before throwing.', use: 'Used in sieges and trench raids. They came back in a big way in the First World War.', ev: 'The first grenadier companies were formed in France in the 1660s.', f: '“Grenade” comes from the French word for pomegranate — a fruit full of seeds.', p: ['grenade', { type: 'round' }], x: ['thunderclap-bomb', 'mills-bomb'] },
  { id: 'puckle-gun', n: 'Puckle gun', c: 'gun', y: 1718, d: '1718', r: 'England', w: 'James Puckle', s: 'A flintlock gun on a tripod with a revolving cylinder — an early attempt at a machine gun.', how: 'A cylinder of 11 chambers was turned by hand to line up each loaded chamber with the barrel.', use: 'It never went into service, but it showed the idea of fast, repeated fire.', ev: 'Puckle demonstrated it firing 63 shots in seven minutes in 1722.', f: 'His patent proposed round bullets for Christians and square ones for Turks — a reminder of the prejudices of the time.', p: ['gun', { type: 'puckle' }], x: ['revolver', 'gatling-gun'] },
  { id: 'turtle-submarine', n: 'Turtle (first military submarine)', c: 'sea', y: 1775, d: '1775', r: 'United States', w: 'David Bushnell', s: 'A one-person, hand-powered wooden submarine built to attach a bomb to a British warship.', how: 'The pilot cranked propellers by hand and let in water to dive, pumping it out to rise.', use: 'Its attack on HMS Eagle in New York harbour in 1776 failed.', ev: 'Sergeant Ezra Lee tried to screw the charge onto the hull but could not get through.', f: 'It looked like two turtle shells joined together, which gave it its name.', p: ['submarine', { type: 'turtle' }], x: ['hunley', 'nuclear-submarine'] },
  { id: 'mysorean-rockets', n: 'Mysorean rockets', c: 'art', y: 1780, d: '1780s', r: 'Kingdom of Mysore (India)', w: 'Hyder Ali and Tipu Sultan', s: 'The first rockets with iron cases, which could fly about 2 km and frighten and scatter troops.', how: 'An iron tube held more powder at higher pressure than paper or bamboo, giving longer range.', use: 'Mysore used thousands against the British East India Company.', ev: 'They caused heavy British losses at the Battle of Pollilur in 1780.', f: 'Captured rockets inspired the British Congreve rocket.', p: ['firearrow'], x: ['fire-arrow', 'congreve-rocket'] },
  // ---------------- Industrial age
  { id: 'congreve-rocket', n: 'Congreve rocket', c: 'art', y: 1804, d: '1804', r: 'United Kingdom', w: 'William Congreve', s: 'British military rockets based on captured Mysorean ones, fired in volleys from ships and land.', how: 'An iron case and a long stick for balance gave range of up to 3 km, though aim was poor.', use: 'Used in the Napoleonic Wars and the War of 1812.', ev: 'The “rockets’ red glare” in the US national anthem describes Congreve rockets at Fort McHenry in 1814.', f: 'They were used in the bombardment of Copenhagen in 1807, setting much of the city on fire.', p: ['firearrow'], x: ['mysorean-rockets', 'v2-rocket'] },
  { id: 'percussion-cap', n: 'Percussion lock', c: 'gun', y: 1807, d: '1807', r: 'Scotland, later USA and England', w: 'Rev. Alexander Forsyth; caps by Joshua Shaw', s: 'A gun fired by a hammer hitting a small cap of shock-sensitive chemical — reliable even in rain.', how: 'A tiny copper cap containing a chemical that explodes when struck was placed on a nipple; the hammer set it off.', use: 'Replaced the flintlock by the 1840s and made later cartridges possible.', ev: 'Most guns of the American Civil War were percussion rifles.', f: 'Forsyth was a Scottish minister who wanted a gun that did not scare birds with a flash before firing.', p: ['gun', { type: 'percussion' }], x: ['flintlock', 'minie-ball', 'revolver'] },
  { id: 'revolver', n: 'Revolver', c: 'gun', y: 1836, d: '1836', r: 'United States', w: 'Samuel Colt', s: 'A pistol with a rotating cylinder of five or six chambers, so it fires several shots without reloading.', how: 'Cocking the hammer turns the cylinder to line up the next loaded chamber with the barrel.', use: 'Used by cavalry, police and in the American West. Colt made them in large numbers with standard parts.', ev: 'Texas Rangers made the Colt revolver famous in the 1840s.', f: 'Colt carved his first model of a revolving cylinder from wood while working on a ship.', p: ['gun', { type: 'revolver' }], x: ['pistol', 'puckle-gun', 'semi-auto-pistol'] },
  { id: 'needle-gun', n: 'Needle gun (Dreyse)', c: 'gun', y: 1841, d: '1841', r: 'Prussia (Germany)', w: 'Johann Nikolaus von Dreyse', s: 'A rifle loaded from the back (breech) with a paper cartridge, fired by a long needle — the first bolt-action military rifle.', how: 'A sliding bolt opened the breech. A needle passed through the paper cartridge to hit the primer.', use: 'Soldiers could reload lying down, about five times faster than with muzzle-loaders.', ev: 'Prussia’s needle guns helped crush Austria at Königgrätz in 1866.', f: 'The needle often broke, so soldiers carried spares.', p: ['gun', { type: 'needle' }], x: ['percussion-cap', 'bolt-action'] },
  { id: 'minie-ball', n: 'Minié ball', c: 'gun', y: 1849, d: '1849', r: 'France', w: 'Claude-Étienne Minié', s: 'A soft lead bullet with a hollow base that expanded when fired, gripping the rifling. Rifles became as fast to load as muskets.', how: 'Small enough to drop down the barrel, the hollow base spread out to fit the grooves when the powder fired.', use: 'Rifles were suddenly accurate at 300+ metres, making old close-order tactics deadly.', ev: 'Minié rifles caused most of the huge casualties of the American Civil War.', f: 'Despite the name, it is a cone-shaped bullet, not a ball.', p: ['gun', { type: 'rifle' }], x: ['rifling', 'percussion-cap'] },
  { id: 'naval-mine', n: 'Naval mine', c: 'boom', y: 1855, d: '1850s', r: 'Russia', w: 'Moritz von Jacobi and Immanuel Nobel', s: 'A floating or anchored explosive that blows up when a ship touches it.', how: 'Contact mines had horns that set off the charge when a ship broke them; later ones sensed a ship’s magnetism or noise.', use: 'Russia used them to protect harbours in the Crimean War; they sank many ships in both world wars.', ev: 'At Mobile Bay in 1864, US Admiral Farragut reportedly said “Damn the torpedoes, full speed ahead!” — mines were called torpedoes then.', f: 'Immanuel Nobel was the father of Alfred Nobel, founder of the Nobel Prizes.', p: ['mine'], x: ['torpedo', 'land-mine'] },
  { id: 'ironclad', n: 'Ironclad warship', c: 'sea', y: 1859, d: '1859', r: 'France', w: 'French Navy (La Gloire)', s: 'A steam warship protected by iron armour plates. Wooden warships became obsolete almost overnight.', how: 'Iron plates over the hull stopped cannon balls, and steam engines freed ships from the wind.', use: 'La Gloire (1859) was followed by Britain’s HMS Warrior (1860).', ev: 'In 1862, USS Monitor and CSS Virginia fought the first battle between ironclads, at Hampton Roads.', f: 'Monitor had a revolving gun turret, which all later battleships copied.', p: ['ship', { type: 'ironclad' }], x: ['ship-of-the-line', 'dreadnought'] },
  { id: 'lever-action', n: 'Lever-action repeating rifle', c: 'gun', y: 1860, d: '1860', r: 'United States', w: 'Benjamin Henry; later Winchester', s: 'A rifle that held many cartridges in a tube; working a lever under the stock loaded the next one.', how: 'Moving the lever down and up ejected the empty case and pushed a fresh cartridge into the chamber.', use: 'Used in the Civil War and the American West; the Winchester 1873 became famous.', ev: 'Confederate soldiers called the Henry “that damned Yankee rifle you load on Sunday and shoot all week”.', f: 'Lakota and Cheyenne warriors used repeating rifles at the Battle of the Little Bighorn in 1876.', p: ['gun', { type: 'lever' }], x: ['revolver', 'bolt-action'] },
  { id: 'gatling-gun', n: 'Gatling gun', c: 'gun', y: 1862, d: '1862', r: 'United States', w: 'Richard Gatling', s: 'A hand-cranked gun with a ring of barrels that turned and fired in turn — the first successful rapid-fire gun.', how: 'Turning the crank rotated the barrels; each loaded, fired and ejected as it went round, so none overheated.', use: 'Used in the late Civil War and in colonial wars.', ev: 'Gatling claimed he hoped his gun would mean smaller armies and fewer deaths from disease.', f: 'Modern aircraft cannon use the same rotating-barrel idea, driven by motors.', p: ['gun', { type: 'gatling' }], x: ['puckle-gun', 'maxim-gun'] },
  { id: 'land-mine', n: 'Land mine', c: 'boom', y: 1862, d: '1862', r: 'United States', w: 'Gabriel Rains (Confederate army)', s: 'A hidden explosive set off by stepping on it or driving over it. It keeps killing long after wars end.', how: 'Pressure on a buried trigger sets off the charge.', use: 'Used massively in both world wars and later conflicts. Millions remain buried around the world.', ev: 'The 1997 Ottawa Treaty, signed by over 160 countries, bans anti-personnel land mines.', f: 'Princess Diana’s 1997 walk through a cleared minefield in Angola drew worldwide attention to the campaign.', p: ['mine', { type: 'land' }], x: ['naval-mine'] },
  { id: 'hunley', n: 'H. L. Hunley submarine', c: 'sea', y: 1864, d: '1864', r: 'United States (Confederacy)', w: 'Horace Hunley and others', s: 'A hand-cranked submarine that became the first to sink an enemy warship.', how: 'Eight crew turned a crank to drive the propeller; a charge on a long pole was rammed into the target.', use: 'It sank USS Housatonic off Charleston in 1864 but was lost with all crew the same night.', ev: 'The wreck was found in 1995 and raised in 2000.', f: 'It sank twice in tests before its final mission, killing Horace Hunley himself.', p: ['submarine'], x: ['turtle-submarine', 'torpedo', 'nuclear-submarine'] },
  { id: 'torpedo', n: 'Self-propelled torpedo', c: 'sea', y: 1866, d: '1866', r: 'Austria-Hungary (Fiume, now Rijeka)', w: 'Robert Whitehead and Giovanni Luppis', s: 'An underwater missile driven by its own engine that hits ships below the waterline.', how: 'Compressed air drove a propeller; a clever valve kept it at a steady depth.', use: 'Torpedo boats, destroyers and submarines made even big battleships vulnerable.', ev: 'The first ship sunk by a self-propelled torpedo was the Ottoman steamer Intibah in 1878.', f: 'The torpedo is named after the electric ray fish, Torpedo.', p: ['torpedo'], x: ['naval-mine', 'hunley', 'u-boat'] },
  { id: 'dynamite', n: 'Dynamite', c: 'boom', y: 1867, d: '1867', r: 'Sweden', w: 'Alfred Nobel', s: 'A safer way to handle nitroglycerin, absorbed into clay-like earth and shaped into sticks.', how: 'Liquid nitroglycerin explodes if shaken. Soaked into absorbent earth, it became stable until set off by a detonator.', use: 'Made for mining and building tunnels and railways, but also used in war.', ev: 'Nobel’s younger brother Emil was killed in a nitroglycerin explosion in 1864.', f: 'A newspaper wrongly printed Nobel’s obituary, calling him “the merchant of death”; he then left his fortune to the Nobel Prizes.', p: ['e', '🧨'], x: ['smokeless-powder', ['invention-atlas.html#dynamite', 'Dynamite in the Invention Atlas']] },
  { id: 'bolt-action', n: 'Bolt-action magazine rifle', c: 'gun', y: 1871, d: '1871', r: 'Germany', w: 'Paul and Wilhelm Mauser', s: 'A rifle loaded by sliding a bolt back and forth, feeding metal cartridges from a magazine.', how: 'Lifting and pulling the bolt ejects the old case; pushing it forward loads a new cartridge from the magazine.', use: 'With smokeless powder, these rifles armed every army in both world wars.', ev: 'The Mauser 1898 design was copied all over the world.', f: 'A trained soldier with a Lee-Enfield could fire about 15 aimed shots a minute (the “mad minute”).', p: ['gun', { type: 'bolt' }], x: ['needle-gun', 'smokeless-powder', 'assault-rifle'] },
  { id: 'barbed-wire', n: 'Barbed wire', c: 'other', y: 1874, d: '1874', r: 'United States', w: 'Joseph Glidden', s: 'Twisted wire with sharp barbs, invented for cattle fences, that became a key defence of trench warfare.', how: 'Thick belts of wire slowed attackers so machine guns could hit them.', use: 'The Western Front in the First World War was protected by thousands of kilometres of it.', ev: 'Soldiers went out at night to repair or cut the wire in “no man’s land”.', f: 'It was patented for farming — and changed the American West by fencing the open range.', p: ['wire'], x: ['maxim-gun', 'tank-mark-i'] },
  { id: 'maxim-gun', n: 'Maxim gun', c: 'gun', y: 1884, d: '1884', r: 'United Kingdom', w: 'Hiram Maxim', s: 'The first fully automatic machine gun: it used each shot’s recoil to load and fire the next, about 600 times a minute.', how: 'The force of each shot pushed parts back, ejecting the case and loading a new cartridge from a cloth belt. A water jacket cooled the barrel.', use: 'Used in colonial wars and then massively in the First World War, where machine guns dominated.', ev: 'On the first day of the Somme, 1 July 1916, machine guns killed or wounded thousands of attackers.', f: 'A friend reportedly told Maxim that to get rich he should invent something to help Europeans “cut each other’s throats”.', p: ['gun', { type: 'maxim' }], x: ['gatling-gun', 'barbed-wire', 'smokeless-powder'] },
  { id: 'smokeless-powder', n: 'Smokeless powder', c: 'boom', y: 1884, d: '1884', r: 'France', w: 'Paul Vieille (Poudre B)', s: 'A propellant made from treated cellulose that burns with little smoke and much more power than black powder.', how: 'It burns cleanly and steadily, giving bullets higher speed without hiding the battlefield in smoke.', use: 'Every army adopted it by 1900, with smaller, faster bullets and longer ranges.', ev: 'Without smoke, soldiers could no longer spot where enemy shooters were.', f: 'Black powder produces so much smoke that Napoleonic battles were often fought half-blind.', p: ['e', '🎇'], x: ['gunpowder', 'bolt-action', 'maxim-gun'] },
  { id: 'semi-auto-pistol', n: 'Semi-automatic pistol', c: 'gun', y: 1893, d: '1893', r: 'Germany', w: 'Hugo Borchardt; later Mauser, Luger, Browning', s: 'A pistol that reloads itself after each shot from a magazine in the grip.', how: 'Recoil pushes the slide back, ejecting the case and cocking the gun; the spring brings it forward with a new round.', use: 'Replaced revolvers in most armies and police forces in the 1900s.', ev: 'John Browning’s M1911 pistol was the US Army’s sidearm for over 70 years.', f: 'The Luger P08 was one of the most collected military pistols of the 20th century.', p: ['gun', { type: 'semiauto' }], x: ['revolver', 'submachine-gun'] },
  { id: 'quick-firing-gun', n: 'Quick-firing field gun (French 75)', c: 'art', y: 1897, d: '1897', r: 'France', w: 'French Army engineers', s: 'The first modern field gun: a recoil system kept it still when it fired, so it could fire 15 shots a minute without re-aiming.', how: 'A hydraulic and air cylinder soaked up the recoil and pushed the barrel back into place.', use: 'Every army copied the idea; artillery caused most deaths in the First World War.', ev: 'French 75s fired millions of shells at the Battle of the Marne in 1914.', f: 'Its recoil system was kept secret for years.', p: ['cannon', { type: 'quickfire' }], x: ['field-artillery', 'howitzer'] },
  { id: 'dreadnought', n: 'Dreadnought battleship', c: 'sea', y: 1906, d: '1906', r: 'United Kingdom', w: 'Royal Navy (Admiral John Fisher)', s: 'HMS Dreadnought had only big guns and fast steam turbines. Every older battleship became out of date.', how: 'Ten 12-inch guns of one size made aiming at long range easier, and turbines gave 21 knots.', use: 'It started a naval arms race between Britain and Germany before the First World War.', ev: 'The biggest dreadnought battle, Jutland in 1916, involved about 250 ships.', f: 'Dreadnought was built in about a year and a day.', p: ['ship', { type: 'dreadnought' }], x: ['ironclad', 'aircraft-carrier'] },
  // ---------------- World Wars
  { id: 'u-boat', n: 'U-boat (diesel-electric submarine)', c: 'sea', y: 1914, d: '1914', r: 'Germany', w: 'Imperial German Navy', s: 'Submarines with diesel engines on the surface and electric motors underwater, able to stay at sea for weeks.', how: 'Diesel engines ran on the surface and charged batteries; batteries powered silent motors when submerged.', use: 'U-boats sank thousands of merchant ships in both world wars, trying to starve Britain.', ev: 'The sinking of the liner Lusitania in 1915 helped turn American opinion against Germany.', f: 'U-boat is short for Unterseeboot, “undersea boat”.', p: ['submarine'], x: ['hunley', 'torpedo', 'radar'] },
  { id: 'bomber', n: 'Bomber aircraft', c: 'air', y: 1914, d: '1914', r: 'Russia', w: 'Igor Sikorsky (Ilya Muromets)', s: 'Planes built to carry bombs far behind the front line, against factories, ports and cities.', how: 'Big, multi-engine planes carried heavy loads; bombsights helped aim from high up.', use: 'Bombing of cities grew from small raids in WWI to vast raids in WWII that killed hundreds of thousands.', ev: 'Picasso’s painting Guernica shows the bombing of a Spanish town in 1937.', f: 'The first bombs dropped from a plane were thrown by hand by an Italian pilot in Libya in 1911.', p: ['plane', { type: 'bomber' }], x: ['fighter-plane', 'stealth-aircraft', 'atomic-bomb'] },
  { id: 'poison-gas', n: 'Poison gas', alt: 'Chemical weapons', c: 'other', y: 1915, d: '1915', r: 'Western Front (Belgium)', w: 'German army, then all sides', s: 'Clouds of chlorine, phosgene and mustard gas used in the First World War. Terrible injuries led to worldwide bans.', how: 'Gas released from cylinders or shells drifted with the wind into enemy trenches.', use: 'Gas killed about 90,000 soldiers in WWI and injured over a million.', ev: 'The first large chlorine gas attack was at Ypres on 22 April 1915. The Geneva Protocol of 1925 and the Chemical Weapons Convention of 1993 ban them.', f: 'The poet Wilfred Owen described a gas attack in his famous poem “Dulce et Decorum Est”.', p: ['cloud'], x: ['gas-mask'] },
  { id: 'gas-mask', n: 'Gas mask', c: 'armour', y: 1915, d: '1915', r: 'Britain, Russia, Germany', w: 'Scientists such as Nikolay Zelinsky and Cluny MacPherson', s: 'A mask with a filter of charcoal and chemicals that cleans the air of poison gas.', how: 'Activated charcoal has a huge surface area that traps gas molecules as air passes through.', use: 'Every soldier carried one by 1916. In WWII, civilians in Britain were given masks too.', ev: 'The first masks in 1915 were pads soaked in chemicals tied over the mouth.', f: 'Children in Britain got colourful “Mickey Mouse” gas masks in 1939.', p: ['gasmask'], x: ['poison-gas', 'steel-helmet'] },
  { id: 'steel-helmet', n: 'Steel helmet', c: 'armour', y: 1915, d: '1915', r: 'France, Britain, Germany', w: 'Adrian (France), John Brodie (UK), Stahlhelm (Germany)', s: 'Soldiers went to war in 1914 in cloth caps. Steel helmets were brought back to stop shell fragments.', how: 'A hard steel bowl deflected small fragments that caused many head wounds.', use: 'Every army adopted them. Modern helmets use Kevlar and other fibres.', ev: 'The British Brodie helmet, shaped like a soup bowl, protected the head from shrapnel falling from above.', f: 'Head wounds dropped sharply after helmets were introduced.', p: ['helmet', { type: 'brodie', mat: 'green' }], x: ['gas-mask', 'kevlar-vest'] },
  { id: 'flamethrower', n: 'Flamethrower', c: 'other', y: 1915, d: '1915', r: 'Germany', w: 'Richard Fiedler', s: 'A backpack tank and nozzle that spray burning fuel.', how: 'Pressurised gas pushes fuel out of a nozzle where it is lit.', use: 'Used against trenches and bunkers in both world wars; today it is restricted.', ev: 'Germany first used flamethrowers in battle at Hooge, Belgium, in July 1915.', f: 'Greek fire, 1,200 years earlier, was a kind of ship-mounted flamethrower.', p: ['flamethrower'], x: ['greek-fire'] },
  { id: 'fighter-plane', n: 'Fighter plane', c: 'air', y: 1915, d: '1915', r: 'Germany and France', w: 'Anthony Fokker and Roland Garros', s: 'A fast plane with a forward-firing machine gun, made to shoot down other aircraft.', how: 'A synchronisation gear timed the gun so bullets passed between the spinning propeller blades.', use: 'Fighter “aces” became famous. In WWII, fighters like the Spitfire defended Britain.', ev: 'The Fokker Eindecker’s synchronised gun gave Germany control of the air in 1915 — the “Fokker scourge”.', f: 'Manfred von Richthofen, the “Red Baron”, shot down 80 planes.', p: ['plane', { type: 'biplane' }], x: ['bomber', 'jet-fighter', 'radar'] },
  { id: 'mills-bomb', n: 'Mills bomb', c: 'boom', y: 1915, d: '1915', r: 'United Kingdom', w: 'William Mills', s: 'A safer hand grenade with a lever and pin, the model for most grenades of the 20th century.', how: 'Pulling the pin let the lever fly off when thrown, starting a short delay before the explosion.', use: 'Used in huge numbers in trench raids. German “stick grenades” had a long handle for throwing.', ev: 'Britain made about 75 million Mills bombs in WWI.', f: 'Its grooved shape gave it the nickname “pineapple”.', p: ['grenade', { type: 'pineapple' }], x: ['hand-grenade'] },
  { id: 'tank-mark-i', n: 'Tank (Mark I)', c: 'land', y: 1916, d: '1916', r: 'United Kingdom', w: 'Ernest Swinton, William Tritton, Walter Wilson', s: 'An armoured vehicle on caterpillar tracks that could cross trenches and barbed wire under machine-gun fire.', how: 'Tracks spread the weight and climbed over trenches; armour stopped bullets.', use: 'Tanks broke the deadlock of trench warfare and became central to war after 1918.', ev: 'Tanks went into battle for the first time at Flers-Courcelette on the Somme, 15 September 1916.', f: 'They were called “tanks” to keep them secret, pretending they were water tanks.', p: ['tank', { era: 'ww1' }], x: ['war-wagon', 't-34', 'main-battle-tank'] },
  { id: 'submachine-gun', n: 'Submachine gun', c: 'gun', y: 1918, d: '1918', r: 'Germany', w: 'Hugo Schmeisser (MP 18)', s: 'A light automatic gun firing pistol cartridges, made for close fighting in trenches and towns.', how: 'It used simple blowback: recoil pushed the bolt back to load the next round.', use: 'Used by storm troops in 1918, gangsters and police in the 1920s, and all armies in WWII.', ev: 'The American Thompson (“Tommy gun”) became famous in the Prohibition era.', f: 'The British Sten gun of WWII cost about £2 to make.', p: ['gun', { type: 'smg' }], x: ['semi-auto-pistol', 'assault-rifle'] },
  { id: 'aircraft-carrier', n: 'Aircraft carrier', c: 'sea', y: 1918, d: '1918', r: 'United Kingdom', w: 'Royal Navy (HMS Argus)', s: 'A ship with a flat deck for planes to take off and land — a floating airfield.', how: 'A long flight deck, lifts to a hangar below and later catapults and arrester wires.', use: 'In WWII, carriers replaced battleships as the most important warships.', ev: 'At Midway in 1942, US carrier planes sank four Japanese carriers, turning the Pacific war.', f: 'HMS Argus was converted from an unfinished passenger liner.', p: ['ship', { type: 'carrier' }], x: ['dreadnought', 'nuclear-submarine'] },
  { id: 'radar', n: 'Radar', c: 'other', y: 1935, d: '1935', r: 'United Kingdom (also USA, Germany)', w: 'Robert Watson-Watt and Arnold Wilkins', s: 'Radio waves sent out and bounced back show where aircraft and ships are, even at night or in fog.', how: 'A transmitter sends pulses; the time until an echo returns gives the distance.', use: 'Britain’s Chain Home radar helped win the Battle of Britain in 1940.', ev: 'The cavity magnetron of 1940 made small, powerful radar possible for planes and ships.', f: 'Microwave ovens were invented after a radar engineer noticed a chocolate bar melting.', p: ['radar'], x: ['fighter-plane', 'u-boat', ['invention-atlas.html#microwave-oven', 'Microwave oven']] },
  { id: 't-34', n: 'Medium tank (T-34)', c: 'land', y: 1940, d: '1940', r: 'Soviet Union', w: 'Mikhail Koshkin', s: 'A fast, sloped-armour Soviet tank, simple to build in huge numbers.', how: 'Sloped armour made shells more likely to bounce off; wide tracks handled mud and snow.', use: 'Over 80,000 T-34s were built. They fought from Moscow to Berlin.', ev: 'The Battle of Kursk in 1943 was one of the largest tank battles in history.', f: 'Koshkin died soon after driving prototypes 2,000 km to Moscow to show them to Stalin.', p: ['tank', { era: 'ww2' }], x: ['tank-mark-i', 'main-battle-tank', 'bazooka'] },
  { id: 'howitzer', n: 'Modern howitzer', c: 'art', y: 1940, d: '20th century', r: 'Worldwide', w: 'Many armies', s: 'A long-range gun that fires shells in a high arc at targets tens of kilometres away, guided by maps, radar and now drones.', how: 'A hydraulic recoil system, a split trail to spread the load and range tables or computers to aim at targets the gun crew cannot see.', use: 'Artillery caused more casualties than any other weapon in both world wars and is still central in wars today.', ev: 'Massive artillery barrages opened battles such as the Somme (1916) and Stalingrad’s counter-offensive (1942).', f: 'Some modern shells can be steered by GPS to land within a few metres of their target.', p: ['cannon', { type: 'howitzer' }], x: ['quick-firing-gun', 'field-artillery'] },
  { id: 'katyusha', n: 'Katyusha rocket launcher', c: 'art', y: 1941, d: '1941', r: 'Soviet Union', w: 'Soviet Red Army', s: 'A truck carrying racks of rockets that could all be fired in a few seconds.', how: 'Simple rails launched many rockets in a salvo, covering a wide area at once.', use: 'Used throughout the Eastern Front; their howling sound gave them the German nickname “Stalin’s organ”.', ev: 'First fired near Orsha in July 1941.', f: 'Katyusha is a nickname for Ekaterina and the title of a popular Russian song.', p: ['e', '🚚'], x: ['hwacha', 'v2-rocket'] },
  { id: 'bazooka', n: 'Bazooka (rocket launcher)', c: 'art', y: 1942, d: '1942', r: 'United States', w: 'Edward Uhl and Leslie Skinner', s: 'A shoulder-fired tube launching a small rocket with a shaped charge that could pierce tank armour.', how: 'A shaped charge focuses its blast into a narrow jet that punches through steel.', use: 'For the first time, a single soldier could stop a tank. Germany copied it as the Panzerschreck.', ev: 'First used in North Africa in 1942.', f: 'It was named after a homemade trombone-like instrument played by comedian Bob Burns.', p: ['gun', { type: 'bazooka' }], x: ['t-34', 'anti-tank-missile'] },
  { id: 'v1', n: 'V-1 flying bomb', c: 'art', y: 1944, d: '1944', r: 'Germany', w: 'German air force', s: 'A pilotless jet-powered bomb that flew to its target and dived down — the first cruise missile.', how: 'A pulse-jet engine pushed it along; a small propeller counted the distance before it dived.', use: 'About 10,000 were fired at England, mostly London, in 1944–45.', ev: 'British pilots sometimes tipped V-1s over by flying alongside and touching their wings.', f: 'Londoners called them “doodlebugs” and listened in fear for the engine to stop.', p: ['missile', { type: 'cruise' }], x: ['v2-rocket', 'cruise-missile'] },
  { id: 'v2-rocket', n: 'V-2 rocket', c: 'art', y: 1944, d: '1944', r: 'Germany', w: 'Wernher von Braun and team', s: 'The first long-range ballistic missile. It flew higher than any object before and fell faster than sound.', how: 'Liquid fuel and liquid oxygen burned in a rocket engine; it climbed above the atmosphere and fell on its target.', use: 'About 3,000 were fired at London, Antwerp and other cities. Thousands of forced labourers died building them.', ev: 'In June 1944, a V-2 test flight became the first human-made object to reach space.', f: 'After the war, von Braun led the US team that built the Saturn V Moon rocket.', p: ['missile', { type: 'v2' }], x: ['v1', 'icbm', ['space-atlas.html#v2-space', 'The V-2 in the Space Atlas']] },
  { id: 'jet-fighter', n: 'Jet fighter', c: 'air', y: 1944, d: '1944', r: 'Germany and the United Kingdom', w: 'Messerschmitt (Me 262) and Gloster (Meteor)', s: 'Fighters powered by jet engines, about 150 km/h faster than the best propeller planes.', how: 'A jet engine sucks in air, squeezes it, burns fuel in it and blasts it out of the back.', use: 'Too late to change WWII, but jets replaced propeller fighters within a few years.', ev: 'The Me 262 was the first jet fighter in combat, in 1944.', f: 'Frank Whittle in Britain and Hans von Ohain in Germany invented jet engines at almost the same time.', p: ['plane', { type: 'jet' }], x: ['fighter-plane', 'swept-jet', ['invention-atlas.html#jet-engine', 'Jet engine']] },
  { id: 'assault-rifle', n: 'Assault rifle (StG 44)', c: 'gun', y: 1944, d: '1944', r: 'Germany', w: 'Hugo Schmeisser', s: 'A rifle firing a shorter cartridge, able to shoot single shots or bursts — the model for most modern infantry rifles.', how: 'A medium-power cartridge made automatic fire controllable while still reaching 300 metres.', use: 'The idea led to the AK-47 and M16, which armed most of the world’s soldiers.', ev: 'Its German name, Sturmgewehr, means “storm rifle”.', f: 'About 400,000 were made before the end of the war.', p: ['gun', { type: 'assault', wood: 1 }], x: ['ak-47', 'm16', 'submachine-gun'] },
  { id: 'military-helicopter', n: 'Military helicopter', c: 'air', y: 1944, d: '1944', r: 'United States', w: 'Igor Sikorsky (R-4)', s: 'Aircraft lifted by spinning rotors that can hover and land almost anywhere.', how: 'The main rotor’s spinning blades are wings; tilting them moves the helicopter in any direction.', use: 'First used to rescue soldiers in Burma in 1944; they carried troops and the wounded in Korea and Vietnam.', ev: 'The Bell UH-1 “Huey” became a symbol of the Vietnam War.', f: 'Helicopters saved many lives by getting wounded soldiers to hospital fast.', p: ['helicopter'], x: ['attack-helicopter', ['surgery-atlas.html#triage', 'Battlefield medicine']] },
  { id: 'atomic-bomb', n: 'Atomic bomb', c: 'other', y: 1945, d: '1945', r: 'United States', w: 'The Manhattan Project (led by J. Robert Oppenheimer and Gen. Leslie Groves)', s: 'A bomb whose energy comes from splitting atoms. Two destroyed Hiroshima and Nagasaki in August 1945, killing over 100,000 people.', how: 'In very general terms: splitting uranium or plutonium atoms releases neutrons that split more atoms in a chain reaction, releasing enormous energy.', use: 'Used only twice in war. Since then, nuclear weapons have been tested and threatened but not used in combat.', ev: 'The first test, Trinity, was in New Mexico on 16 July 1945. The Non-Proliferation Treaty of 1968 tries to stop their spread.', f: 'Survivors of the bombings, called hibakusha, have campaigned for decades for a world without nuclear weapons.', p: ['nuke'], x: ['hydrogen-bomb', 'icbm', ['invention-atlas.html#nuclear-power', 'Nuclear power']] },
  // ---------------- Cold War
  { id: 'ak-47', n: 'AK-47', c: 'gun', y: 1947, d: '1947', r: 'Soviet Union', w: 'Mikhail Kalashnikov', s: 'A simple, tough assault rifle that works in mud, sand and snow. It became the most widely made rifle in history.', how: 'Gas from each shot pushes a piston that works the action; loose-fitting parts keep it working when dirty.', use: 'Tens of millions were made and spread to armies, rebels and criminals worldwide.', ev: 'It appears on the flag of Mozambique.', f: 'Kalashnikov said he wished he had invented a lawnmower instead, to help farmers.', p: ['gun', { type: 'assault', wood: 1 }], x: ['assault-rifle', 'm16'] },
  { id: 'swept-jet', n: 'Swept-wing jet fighter', c: 'air', y: 1949, d: '1949', r: 'Soviet Union and United States', w: 'Mikoyan-Gurevich (MiG-15), North American (F-86 Sabre)', s: 'Fighters with wings angled back, which fly near the speed of sound without shaking.', how: 'Swept wings delay the shock waves that form close to the speed of sound.', use: 'MiG-15s and F-86s fought the first big jet-against-jet battles over Korea.', ev: 'The area of northwest Korea where they fought was called “MiG Alley”.', f: 'In 1947 Chuck Yeager flew faster than sound for the first time, in the Bell X-1.', p: ['plane', { type: 'swept' }], x: ['jet-fighter', 'stealth-aircraft'] },
  { id: 'hydrogen-bomb', n: 'Hydrogen bomb', c: 'other', y: 1952, d: '1952', r: 'United States, then USSR', w: 'Edward Teller, Stanislaw Ulam and others; Andrei Sakharov in the USSR', s: 'A thermonuclear bomb that fuses hydrogen atoms, like the Sun, and can be thousands of times stronger than the Hiroshima bomb.', how: 'In very general terms: an atomic explosion creates the heat and pressure needed to fuse light atoms, releasing even more energy.', use: 'Tested but never used in war. Testing spread radioactive fallout around the world.', ev: 'The Soviet Tsar Bomba of 1961 was the biggest explosion ever made by people. The 1963 Partial Test Ban Treaty stopped tests in the air.', f: 'Andrei Sakharov, who designed Soviet H-bombs, later became a peace campaigner and won the Nobel Peace Prize.', p: ['nuke'], x: ['atomic-bomb', 'icbm'] },
  { id: 'nuclear-submarine', n: 'Nuclear submarine', c: 'sea', y: 1954, d: '1954', r: 'United States', w: 'Admiral Hyman Rickover (USS Nautilus)', s: 'A submarine powered by a nuclear reactor that can stay underwater for months.', how: 'A reactor heats water into steam to spin turbines, without needing air, so the sub need not surface.', use: 'Submarines carrying nuclear missiles, hidden in the oceans, became a key part of Cold War deterrence.', ev: 'In 1958, Nautilus became the first vessel to travel under the North Pole.', f: 'Nuclear subs can make their own drinking water and oxygen from sea water.', p: ['submarine'], x: ['u-boat', 'icbm'] },
  { id: 'anti-tank-missile', n: 'Guided anti-tank missile', c: 'art', y: 1955, d: '1955', r: 'France', w: 'Nord Aviation (SS.10)', s: 'A missile a soldier steers onto a tank, at first along thin wires.', how: 'Early types were steered with a joystick; signals went down a wire unrolling behind the missile.', use: 'In the 1973 Yom Kippur War, Egyptian infantry with missiles destroyed many Israeli tanks.', ev: 'The Soviet 9M14 Malyutka (“Sagger”) became one of the most widely used.', f: 'Modern ones can be “fire and forget”, homing on the target by themselves.', p: ['missile', { type: 'atgm' }], x: ['bazooka', 'main-battle-tank'] },
  { id: 'icbm', n: 'Intercontinental ballistic missile', alt: 'ICBM', c: 'art', y: 1957, d: '1957', r: 'Soviet Union', w: 'Sergei Korolev (R-7)', s: 'A rocket that can carry a nuclear warhead across the world in about 30 minutes.', how: 'It climbs into space, coasts in an arc, and its warheads fall back to Earth at very high speed.', use: 'Thousands were built by the USA and USSR. Treaties like SALT, INF and START reduced their numbers.', ev: 'In the Cuban Missile Crisis of 1962, the world came close to nuclear war over missiles in Cuba.', f: 'The same R-7 rocket launched Sputnik, the first satellite, in 1957 — and still launches Soyuz spacecraft.', p: ['missile', { type: 'icbm' }], x: ['v2-rocket', 'hydrogen-bomb', ['space-atlas.html#sputnik-1', 'Sputnik 1']] },
  { id: 'sam', n: 'Surface-to-air missile', c: 'art', y: 1957, d: '1957', r: 'Soviet Union', w: 'Soviet air defence (S-75 Dvina, “SA-2”)', s: 'A guided missile launched from the ground to shoot down aircraft.', how: 'Radar tracked the plane and guided the missile towards it.', use: 'Missiles made high-flying bombers vulnerable and changed air warfare.', ev: 'In 1960, an S-75 missile shot down Gary Powers’ U-2 spy plane over the USSR.', f: 'The U-2 incident wrecked a planned summit between the US and Soviet leaders.', p: ['missile', { type: 'sam' }], x: ['missile-defence', 'stealth-aircraft'] },
  { id: 'm16', n: 'M16 rifle', c: 'gun', y: 1964, d: '1964', r: 'United States', w: 'Eugene Stoner (ArmaLite AR-15)', s: 'A light assault rifle of aluminium and plastic, firing small, fast bullets.', how: 'Gas from each shot travels back through a tube to push the bolt directly.', use: 'Adopted by the US Army in Vietnam; versions are still used worldwide.', ev: 'Early M16s jammed in Vietnam until cleaning kits and better ammunition were issued.', f: 'Soldiers could carry nearly twice as many of its small cartridges as older rifle rounds.', p: ['gun', { type: 'assault', handle: 1 }], x: ['ak-47', 'assault-rifle'] },
  { id: 'night-vision', n: 'Night vision', c: 'other', y: 1965, d: '1960s', r: 'United States', w: 'US Army night vision laboratory', s: 'Goggles that make faint light thousands of times brighter, letting soldiers see in the dark.', how: 'Light hits a plate that releases electrons; these are multiplied and hit a green screen, building a bright image.', use: 'Used from the Vietnam War onward. Thermal cameras that see heat came later.', ev: 'Night vision gave a big advantage in night fighting in the 1991 Gulf War.', f: 'The image is green because human eyes can tell apart more shades of green than other colours.', p: ['e', '🥽'], x: ['radar'] },
  { id: 'attack-helicopter', n: 'Attack helicopter', c: 'air', y: 1967, d: '1967', r: 'United States', w: 'Bell (AH-1 Cobra)', s: 'A narrow, armed helicopter built to attack tanks and support soldiers on the ground.', how: 'A two-seat, slim body is hard to hit; guns, rockets and missiles hang from stub wings.', use: 'First used in Vietnam; later types like the Apache and Mi-24 carry anti-tank missiles.', ev: 'The Soviet Mi-24 “Hind” was used heavily in Afghanistan in the 1980s.', f: 'The pilot of an Apache can aim a gun just by turning their head.', p: ['helicopter', { attack: 1, color: '#4b5a3a' }], x: ['military-helicopter', 'anti-tank-missile'] },
  { id: 'laser-guided-bomb', n: 'Laser-guided bomb', c: 'air', y: 1968, d: '1968', r: 'United States', w: 'Texas Instruments (Paveway)', s: 'A bomb with fins and a sensor that follows a laser spot pointed at the target.', how: 'A laser marks the target; the bomb’s sensor sees the reflected light and steers towards it.', use: 'Made bombing far more accurate. In Vietnam, one destroyed a bridge that hundreds of earlier raids had missed.', ev: 'The Thanh Hoa Bridge was finally dropped by laser-guided bombs in 1972.', f: 'Precision weapons mean fewer bombs, but mistakes in targeting still kill civilians.', p: ['missile', { type: 'bomb', laser: 1 }], x: ['gps-guided-bomb', 'stealth-aircraft'] },
  { id: 'kevlar-vest', n: 'Kevlar body armour', c: 'armour', y: 1975, d: '1975', r: 'United States', w: 'Stephanie Kwolek (Kevlar, 1965)', s: 'A vest of very strong woven fibres that can stop many bullets and fragments.', how: 'Layers of Kevlar catch a bullet and spread its energy, like a net catching a ball.', use: 'Worn by police from the 1970s; with ceramic plates it protects soldiers from rifle bullets.', ev: 'Kevlar vests are credited with saving thousands of police officers’ lives.', f: 'Kwolek discovered Kevlar while trying to make light, strong fibres for car tyres.', p: ['armour', { type: 'kevlar' }], x: ['steel-helmet', 'plate-armour'] },
  { id: 'main-battle-tank', n: 'Modern main battle tank', c: 'land', y: 1979, d: '1979', r: 'West Germany, United States, United Kingdom', w: 'Krauss-Maffei (Leopard 2), General Dynamics (M1 Abrams)', s: 'Heavy tanks with layered (composite) armour, big guns and computers that aim while moving.', how: 'Composite armour of ceramics and metals defeats shaped charges; a gun stabiliser keeps aim on rough ground.', use: 'Fought in the Gulf Wars and Ukraine; drones and missiles now threaten them.', ev: 'In the 1991 Gulf War, M1 Abrams tanks fought large tank battles in the desert.', f: 'The M1 Abrams uses a gas turbine engine, like a helicopter.', p: ['tank', { era: 'modern' }], x: ['t-34', 'anti-tank-missile', 'fpv-drone'] },
  { id: 'stealth-aircraft', n: 'Stealth aircraft', c: 'air', y: 1981, d: '1981', r: 'United States', w: 'Lockheed Skunk Works (F-117), Northrop (B-2)', s: 'Planes shaped and coated so radar can hardly see them.', how: 'Flat angled surfaces bounce radar waves away from the receiver, and special coatings absorb them.', use: 'Used in Panama (1989), the Gulf War (1991) and later conflicts.', ev: 'The F-117 first flew in 1981 but was kept secret until 1988.', f: 'Its faceted shape was worked out with early computers that could only calculate flat surfaces.', p: ['plane', { type: 'stealth' }], x: ['swept-jet', 'sam', 'drone-armed'] },
  { id: 'cruise-missile', n: 'Tomahawk cruise missile', c: 'art', y: 1983, d: '1983', r: 'United States', w: 'General Dynamics', s: 'A small, pilotless jet that flies low over land and sea to hit a target over 1,000 km away.', how: 'It compares the ground below with stored maps, later using GPS, to find its way.', use: 'First used in combat in the 1991 Gulf War, launched from ships and submarines.', ev: 'Hundreds were fired on the first nights of the 1991 Gulf War.', f: 'It is a modern descendant of the V-1 flying bomb.', p: ['missile', { type: 'cruise' }], x: ['v1', 'gps-guided-bomb', 'hypersonic-missile'] },
  // ---------------- Modern era
  { id: 'gps-guided-bomb', n: 'GPS-guided bomb (JDAM)', c: 'air', y: 1997, d: '1997', r: 'United States', w: 'Boeing', s: 'A kit that turns an ordinary bomb into a guided one using satellite navigation.', how: 'A tail kit with GPS and fins steers the bomb to a set position, in any weather.', use: 'Used widely in Afghanistan and Iraq. Cheap and accurate, but only as good as the target information.', ev: 'GPS was developed by the US military; civilians now use it in every phone.', f: 'A JDAM kit costs much less than the bomb used to miss.', p: ['missile', { type: 'bomb' }], x: ['laser-guided-bomb', ['space-atlas.html#gps', 'GPS satellites']] },
  { id: 'drone-armed', n: 'Armed drone', c: 'air', y: 2001, d: '2001', r: 'United States', w: 'General Atomics (MQ-1 Predator)', s: 'A pilotless aircraft flown from the ground, often from another continent, that can watch for hours and fire missiles.', how: 'Satellites relay video and commands between the drone and its crew.', use: 'Used for surveillance and strikes in Afghanistan, Pakistan, Yemen and elsewhere, raising big legal and moral debates.', ev: 'The first armed Predator strikes took place in Afghanistan in 2001.', f: 'Pilotless planes were first tested in 1917; modern drones were possible after GPS and satellite links.', p: ['drone'], x: ['fpv-drone', 'stealth-aircraft'] },
  { id: 'railgun', n: 'Railgun', c: 'art', y: 2008, d: '2008', r: 'United States', w: 'US Navy research', s: 'A gun that fires a metal slug using electricity and magnetism instead of gunpowder.', how: 'A huge electric current flows through two rails and the projectile, creating a magnetic force that pushes it out.', use: 'Tested by the US Navy until 2021 but not used; the rails wore out quickly. Japan is still testing one.', ev: 'In 2010, a US Navy railgun test fired a projectile with a record 33 megajoules of energy.', f: 'Science-fiction writers imagined railguns long before engineers built them.', p: ['railgun'], x: ['laser-weapon', 'quick-firing-gun'] },
  { id: 'cyber-weapon', n: 'Cyber weapon (Stuxnet)', c: 'other', y: 2010, d: '2010', r: 'Iran (target)', w: 'Widely believed to be the USA and Israel', s: 'A computer worm that physically damaged machines — the first known digital weapon to break real equipment.', how: 'It spread through USB sticks and networks, found specific industrial controllers, and made centrifuges spin wrongly while showing normal readings.', use: 'It damaged about 1,000 centrifuges at Natanz in Iran. Cyber attacks on power grids and hospitals have followed.', ev: 'Security researchers discovered Stuxnet in 2010.', f: 'Countries are still debating how the laws of war apply to cyber attacks.', p: ['cyber'], x: ['radar'] },
  { id: 'missile-defence', n: 'Missile defence (Iron Dome)', c: 'other', y: 2011, d: '2011', r: 'Israel', w: 'Rafael Advanced Defense Systems', s: 'A system of radar and interceptor missiles that shoots down incoming rockets and shells.', how: 'Radar tracks a rocket, a computer predicts where it will land, and an interceptor is fired only at those heading for towns.', use: 'Used since 2011; it has intercepted thousands of rockets.', ev: 'Earlier, US Patriot missiles tried to intercept Iraqi Scud missiles in the 1991 Gulf War.', f: 'Hitting a missile with a missile has been compared to hitting a bullet with a bullet.', p: ['dome'], x: ['sam', 'laser-weapon'] },
  { id: 'laser-weapon', n: 'Laser weapon', c: 'other', y: 2014, d: '2014', r: 'United States', w: 'US Navy (LaWS on USS Ponce)', s: 'A powerful beam of light that heats a drone or small boat until it fails.', how: 'A laser focuses energy on one spot; it costs only electricity per shot.', use: 'Tested on ships and land against drones and small rockets. Lasers that blind people are banned (1995 protocol).', ev: 'In 2014 the US Navy put a working laser weapon on USS Ponce in the Persian Gulf.', f: 'The beam is invisible — the target just starts to burn.', p: ['laser'], x: ['railgun', 'missile-defence', ['invention-atlas.html#laser', 'Laser']] },
  { id: 'hypersonic-missile', n: 'Hypersonic missile', c: 'art', y: 2019, d: '2019', r: 'Russia and China', w: 'Russian and Chinese weapons programmes', s: 'A missile that flies at more than five times the speed of sound and can change direction, making it hard to intercept.', how: 'A glide vehicle is boosted to high speed by a rocket, then glides and steers through the upper atmosphere.', use: 'Russia announced its Avangard in 2019; other countries are developing their own.', ev: 'Russia says it has used Kinzhal missiles in Ukraine since 2022.', f: 'At these speeds, the air around the missile becomes hot enough to glow.', p: ['missile', { type: 'hypersonic' }], x: ['icbm', 'cruise-missile', 'missile-defence'] },
  { id: 'fpv-drone', n: 'Small attack drones', c: 'air', y: 2022, d: '2022', r: 'Ukraine and Russia', w: 'Soldiers and volunteers on both sides', s: 'Cheap hobby-style drones, flown with video goggles, that carry small explosives to targets.', how: 'A pilot sees through the drone’s camera (first-person view) and steers it directly.', use: 'Used in huge numbers in the war in Ukraine, changing how armies protect soldiers and vehicles.', ev: 'Both sides build hundreds of thousands per year; jamming and anti-drone defences race to keep up.', f: 'Many parts come from the same shops that sell racing drones for sport.', p: ['drone', { type: 'quad' }], x: ['drone-armed', 'main-battle-tank'] }
];
